@property --bko-colophon-letters { syntax: '<integer>'; inherits: true; initial-value: 0; }
@property --bko-colophon-mins { syntax: '<integer>'; inherits: true; initial-value: 0; }

.bko-colophon {
  /* re-theme with these four */
  --bko-colophon-paper: oklch(96.6% 0.016 84);
  --bko-colophon-ink: oklch(21% 0.018 52);
  --bko-colophon-accent: oklch(50% 0.165 29);
  --bko-colophon-mark: oklch(89% 0.135 98);

  --bko-colophon-muted: color-mix(in oklch, var(--bko-colophon-ink) 62%, var(--bko-colophon-paper));
  --bko-colophon-faint: color-mix(in oklch, var(--bko-colophon-ink) 40%, var(--bko-colophon-paper));
  --bko-colophon-rule: color-mix(in oklch, var(--bko-colophon-ink) 16%, transparent);
  --bko-colophon-wash: color-mix(in oklch, var(--bko-colophon-ink) 4%, var(--bko-colophon-paper));
  --bko-colophon-serif: ui-serif, "New York", "Iowan Old Style", Charter, Georgia, serif;
  --bko-colophon-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --bko-colophon-out: cubic-bezier(.2, .8, .2, 1);
  --bko-colophon-wipe: cubic-bezier(.7, 0, .24, 1);
  --bko-colophon-gutter: clamp(16px, 5.2cqi, 64px);

  container-type: inline-size;
  container-name: bko-colophon;
  box-sizing: border-box;
  width: 100%;
  background: var(--bko-colophon-paper);
  color: var(--bko-colophon-ink);
  font: 400 15px/1.55 var(--bko-colophon-sans);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, blockquote, fieldset, figure) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & [hidden] { display: none !important; }
  & :where(a, button, input):focus-visible {
    outline: 2px solid var(--bko-colophon-accent);
    outline-offset: 3px;
    border-radius: 2px;
  }
}

.bko-colophon-vh {
  position: absolute !important;
  width: 1px; height: 1px; margin: -1px; padding: 0; border: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

.bko-colophon-in {
  padding: clamp(36px, 6cqi, 76px) var(--bko-colophon-gutter) clamp(22px, 3cqi, 32px);
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "mast" "letters" "nav" "base";
  gap: clamp(30px, 5cqi, 56px) clamp(32px, 6cqi, 88px);
  max-width: 1320px;
  margin-inline: auto;
}

/* ---------- masthead ---------- */
.bko-colophon-mast {
  grid-area: mast;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 32px;
  padding-bottom: clamp(14px, 2cqi, 22px);
  border-bottom: 3px double var(--bko-colophon-ink);
}
.bko-colophon-logo {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1.2cqi, 14px);
  font-family: var(--bko-colophon-serif);
  font-size: clamp(30px, 4.2cqi + 12px, 64px);
  font-weight: 600;
  letter-spacing: -.025em;
  line-height: .95;
  & svg {
    width: .78em; height: .78em; flex: none;
    fill: none; stroke: var(--bko-colophon-accent); stroke-width: 1.6;
    stroke-linecap: round; stroke-linejoin: round;
    transition: transform .6s var(--bko-colophon-out);
  }
  & i { font-weight: 400; font-size: .52em; letter-spacing: 0; color: var(--bko-colophon-muted); vertical-align: .3em; }
  &:hover svg { transform: rotate(-12deg) translateY(-2px); }
}
.bko-colophon-issue {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 0;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--bko-colophon-muted);
  font-variant-numeric: tabular-nums;
  & span + span::before { content: "·"; margin-inline: .7em; color: var(--bko-colophon-faint); }
  & span:nth-child(3) { display: none; }
}

/* ---------- letters ---------- */
.bko-colophon-letters { grid-area: letters; display: grid; gap: 14px; align-content: start; min-width: 0; }
.bko-colophon-h {
  font-family: var(--bko-colophon-serif);
  font-size: clamp(28px, 2.6cqi + 14px, 46px);
  font-weight: 500;
  line-height: 1.04;
  letter-spacing: -.02em;
  text-wrap: balance;
}
.bko-colophon-dek {
  color: var(--bko-colophon-muted);
  max-width: 46ch;
  text-wrap: pretty;
}
.bko-colophon-form { display: grid; gap: 14px; margin-top: 6px; }
.bko-colophon-picks { border: 0; min-width: 0; border-top: 1px solid var(--bko-colophon-ink); }

.bko-colophon-pick {
  position: relative;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  grid-template-areas: "box title" ". meta" ". desc";
  column-gap: 12px;
  row-gap: 2px;
  padding: 13px 10px 13px 4px;
  border-bottom: 1px solid var(--bko-colophon-rule);
  cursor: pointer;
  transition: background-color .25s var(--bko-colophon-out);
  &:hover { background: var(--bko-colophon-wash); }
  & input {
    grid-area: box;
    width: 17px; height: 17px;
    margin: 4px 0 0;
    accent-color: var(--bko-colophon-ink);
    cursor: pointer;
  }
  &:has(input:focus-visible) { outline: 2px solid var(--bko-colophon-accent); outline-offset: -2px; }
  & input:focus-visible { outline: none; }
}
.bko-colophon-pt {
  grid-area: title;
  font-family: var(--bko-colophon-serif);
  font-size: clamp(17px, .5cqi + 14px, 20px);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -.005em;
  & > span { position: relative; isolation: isolate; }
  & > span::before {
    content: "";
    position: absolute;
    inset: .12em -.28em -.02em -.22em;
    z-index: -1;
    background: var(--bko-colophon-mark);
    border-radius: .18em .5em .22em .4em;
    transform: skewX(-8deg) rotate(-.8deg);
    clip-path: inset(0 100% 0 0);
    transition: clip-path .5s var(--bko-colophon-wipe);
  }
}
.bko-colophon-pick:has(input:checked) .bko-colophon-pt > span::before {
  clip-path: inset(0 0 0 0);
  transition-delay: 40ms;
}
.bko-colophon-pm {
  grid-area: meta;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--bko-colophon-accent);
  font-variant-numeric: tabular-nums;
}
.bko-colophon-pd { grid-area: desc; color: var(--bko-colophon-muted); font-size: 14px; text-wrap: pretty; }

/* the tally sentence: registered integers rendered through counters */
.bko-colophon-tally {
  --bko-colophon-letters: 8;
  --bko-colophon-mins: 100;
  font-family: var(--bko-colophon-serif);
  font-style: italic;
  font-size: clamp(16px, .4cqi + 14px, 18.5px);
  line-height: 1.4;
  min-height: 2.8em;
  text-wrap: pretty;
  transition: --bko-colophon-letters .7s var(--bko-colophon-out), --bko-colophon-mins 1s var(--bko-colophon-out);
  & .bko-colophon-none { display: none; color: var(--bko-colophon-accent); }
  &[data-zero] .bko-colophon-some { display: none; }
  &[data-zero] .bko-colophon-none { display: inline; }
}
.bko-colophon-num {
  font-style: normal;
  font-family: var(--bko-colophon-sans);
  font-weight: 700;
  font-size: .94em;
  font-variant-numeric: tabular-nums;
  letter-spacing: -.01em;
  color: var(--bko-colophon-accent);
  &[data-k="letters"]::after { counter-reset: bko-colophon-l var(--bko-colophon-letters); content: counter(bko-colophon-l); }
  &[data-k="mins"]::after { counter-reset: bko-colophon-m var(--bko-colophon-mins); content: counter(bko-colophon-m); }
}

.bko-colophon-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 10px;
}
.bko-colophon-email input {
  width: 100%;
  font: inherit;
  font-size: 16px;
  color: inherit;
  padding: 12px 2px 10px;
  background: transparent;
  border: 0;
  border-bottom: 2px solid var(--bko-colophon-ink);
  border-radius: 0;
  transition: border-color .2s;
  &::placeholder { color: var(--bko-colophon-faint); }
  &:focus-visible { outline: none; border-bottom-color: var(--bko-colophon-accent); }
  &[aria-invalid="true"] { border-bottom-color: var(--bko-colophon-accent); }
}
.bko-colophon-go {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 46px;
  padding: 0 18px 0 20px;
  font: 600 14.5px/1 var(--bko-colophon-sans);
  letter-spacing: .01em;
  color: var(--bko-colophon-paper);
  background: var(--bko-colophon-ink);
  border: 0;
  border-radius: 2px;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color .25s, transform .3s var(--bko-colophon-out);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: transform .35s var(--bko-colophon-out); }
  &:hover { background: var(--bko-colophon-accent); }
  &:hover svg { transform: translateX(3px); }
  &:active { transform: translateY(1px); }
  &[aria-disabled="true"] { background: var(--bko-colophon-faint); cursor: not-allowed; }
  &[aria-disabled="true"] svg { transform: none; }
}
.bko-colophon-err { color: var(--bko-colophon-accent); font-size: 13.5px; font-weight: 500; }
.bko-colophon-fine { color: var(--bko-colophon-muted); font-size: 12.5px; }
.bko-colophon-letters[data-shake] .bko-colophon-picks { animation: bko-colophon-nudge .42s cubic-bezier(.36, .07, .19, .97); }
@keyframes bko-colophon-nudge {
  20%, 60% { transform: translateX(-5px); }
  40%, 80% { transform: translateX(4px); }
}

/* confirmation */
.bko-colophon-done {
  position: relative;
  display: grid;
  gap: 12px;
  margin-top: 6px;
  padding: clamp(20px, 3cqi, 30px);
  border: 1px solid var(--bko-colophon-ink);
  background: var(--bko-colophon-wash);
  transition: opacity .5s var(--bko-colophon-out), transform .6s var(--bko-colophon-out), clip-path .7s var(--bko-colophon-wipe);
  clip-path: inset(0 0 0 0);
  &:focus { outline: none; }
  &[hidden] { display: none; }
  @starting-style {
    opacity: 0;
    transform: translateY(10px);
    clip-path: inset(0 0 100% 0);
  }
}
.bko-colophon-stamp {
  position: absolute;
  top: 14px; right: 14px;
  width: 84px; height: 84px;
  display: grid;
  place-content: center;
  text-align: center;
  border: 2px solid var(--bko-colophon-accent);
  border-radius: 50%;
  color: var(--bko-colophon-accent);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .14em;
  line-height: 1.25;
  text-transform: uppercase;
  transform: rotate(-14deg);
  opacity: .9;
  animation: bko-colophon-stamp .5s .25s cubic-bezier(.3, 1.6, .5, 1) backwards;
  & span:first-child { font-family: var(--bko-colophon-serif); font-size: 17px; letter-spacing: .02em; text-transform: none; font-style: italic; }
}
@keyframes bko-colophon-stamp {
  from { transform: rotate(-30deg) scale(1.7); opacity: 0; }
}
.bko-colophon-dh {
  font-family: var(--bko-colophon-serif);
  font-size: clamp(24px, 1.6cqi + 16px, 32px);
  font-weight: 500;
  letter-spacing: -.015em;
  padding-right: 92px;
}
.bko-colophon-dp { max-width: 48ch; text-wrap: pretty; padding-right: 40px; }
.bko-colophon-dl {
  display: grid;
  border-top: 1px solid var(--bko-colophon-rule);
  & li {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    padding: 8px 0;
    border-bottom: 1px solid var(--bko-colophon-rule);
    font-size: 14px;
    opacity: 0;
    animation: bko-colophon-row .5s calc(.35s + var(--i, 0) * 70ms) var(--bko-colophon-out) forwards;
  }
  & b { font-family: var(--bko-colophon-serif); font-weight: 600; }
  & span { color: var(--bko-colophon-muted); font-variant-numeric: tabular-nums; text-align: right; }
}
@keyframes bko-colophon-row {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
.bko-colophon-back {
  justify-self: start;
  font: 600 13.5px/1 var(--bko-colophon-sans);
  color: var(--bko-colophon-ink);
  background: none;
  border: 0;
  padding: 6px 0;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: var(--bko-colophon-faint);
  text-underline-offset: 4px;
  &:hover { text-decoration-color: var(--bko-colophon-accent); }
}

/* ---------- link columns ---------- */
.bko-colophon-nav {
  grid-area: nav;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 28px 20px;
  align-content: start;
}
.bko-colophon-col {
  display: grid;
  gap: 12px;
  align-content: start;
  & h3 {
    font-size: 11.5px;
    font-weight: 700;
    letter-spacing: .14em;
    text-transform: uppercase;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--bko-colophon-ink);
  }
  & ul { display: grid; gap: 7px; }
  & a {
    font-size: 15px;
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 4px;
    text-decoration-color: transparent;
    transition: text-decoration-color .25s, color .25s;
  }
  & a:hover { color: var(--bko-colophon-accent); text-decoration-color: currentColor; }
  & small { font-size: 11.5px; color: var(--bko-colophon-faint); font-variant-numeric: tabular-nums; margin-left: 4px; }
}
.bko-colophon-quote {
  grid-column: 1 / -1;
  position: relative;
  padding: 18px 0 0 34px;
  border-top: 1px solid var(--bko-colophon-rule);
  & p {
    font-family: var(--bko-colophon-serif);
    font-style: italic;
    font-size: clamp(19px, 1.1cqi + 13px, 25px);
    line-height: 1.25;
    letter-spacing: -.01em;
    text-wrap: balance;
    text-indent: -.42em;
  }
  &::before {
    content: "";
    position: absolute;
    left: 0; top: 24px;
    width: 18px; height: 3px;
    background: var(--bko-colophon-accent);
  }
  & cite { display: block; margin-top: 8px; font-style: normal; font-size: 12.5px; color: var(--bko-colophon-muted); letter-spacing: .02em; }
}

/* ---------- base line ---------- */
.bko-colophon-base {
  grid-area: base;
  display: grid;
  gap: 10px;
  padding-top: 16px;
  border-top: 1px solid var(--bko-colophon-ink);
  font-size: 12.5px;
  color: var(--bko-colophon-muted);
}
.bko-colophon-set { font-family: var(--bko-colophon-serif); font-style: italic; font-size: 14px; color: var(--bko-colophon-ink); }
.bko-colophon-copy { font-variant-numeric: tabular-nums; }
.bko-colophon-legal {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  & a { color: var(--bko-colophon-ink); transition: color .2s; }
  & a:hover { color: var(--bko-colophon-accent); }
}

@container bko-colophon (max-width: 519.98px) {
  .bko-colophon-quote {
    grid-column: auto;
    align-self: start;
    margin-top: 30px;
    padding: 14px 0 0;
    border-top: 1px solid var(--bko-colophon-ink);
    & p { font-size: 18px; text-indent: 0; }
    &::before { display: none; }
  }
}
@container bko-colophon (min-width: 520px) {
  .bko-colophon-issue span:nth-child(3) { display: inline; }
  .bko-colophon-nav { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bko-colophon-field { grid-template-columns: minmax(0, 1fr) auto; align-items: end; }
  .bko-colophon-pick {
    grid-template-columns: 22px minmax(0, 1fr) auto;
    grid-template-areas: "box title meta" ". desc desc";
    & .bko-colophon-pm { align-self: center; }
  }
}
@container bko-colophon (min-width: 800px) {
  .bko-colophon-in {
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 1fr);
    grid-template-areas: "mast mast" "letters nav" "base base";
  }
  .bko-colophon-nav { padding-top: 8px; row-gap: 40px; }
  .bko-colophon-quote p { font-size: clamp(22px, 1.4cqi + 12px, 30px); }
  .bko-colophon-base {
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: baseline;
    column-gap: 32px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bko-colophon {
    & .bko-colophon-pt > span::before { transition: none; }
    & .bko-colophon-tally { transition: none; }
    & .bko-colophon-done { transition: opacity .2s linear; transform: none; clip-path: none; }
    & .bko-colophon-stamp { animation: none; }
    & .bko-colophon-dl li { animation: none; opacity: 1; }
    & .bko-colophon-logo svg, & .bko-colophon-go, & .bko-colophon-go svg { transition: none; }
    & .bko-colophon-letters[data-shake] .bko-colophon-picks { animation: none; }
  }
  @starting-style {
    .bko-colophon .bko-colophon-done { opacity: 0; transform: none; clip-path: none; }
  }
}

