const letters = root.querySelector('.bko-colophon-letters');
const form = root.querySelector('.bko-colophon-form');
const picks = [...root.querySelectorAll('.bko-colophon-pick input')];
const tally = root.querySelector('.bko-colophon-tally');
const live = root.querySelector('[data-live]');
const go = root.querySelector('.bko-colophon-go');
const goLabel = go.querySelector('[data-label]');
const email = form.querySelector('input[type="email"]');
const err = root.querySelector('[data-err]');
const done = root.querySelector('.bko-colophon-done');
const back = root.querySelector('.bko-colophon-back');

// unique ids so two copies of the footer on one page never share them
const uid = 'bko-colophon-' + Math.random().toString(36).slice(2, 8);
err.id = uid + '-err';

const names = {
  sunday: 'The Sunday Long Read', margins: 'Margins', field: 'Field Notes', index: 'The Index'
};
const when = { sunday: 'Sundays, 08:00', margins: 'Every other Tuesday', field: 'Thursdays, 12:00', index: 'Weekdays, 07:00' };
const fmtDay = new Intl.DateTimeFormat('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
const fmtStamp = new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short' });

function chosen() { return picks.filter((p) => p.checked); }

function update(announce) {
  let n = 0, mins = 0;
  const on = chosen();
  on.forEach((p) => { n += +p.dataset.n; mins += +p.dataset.n * +p.dataset.min; });
  tally.style.setProperty('--bko-colophon-letters', n);
  tally.style.setProperty('--bko-colophon-mins', mins);
  tally.toggleAttribute('data-zero', on.length === 0);
  go.setAttribute('aria-disabled', on.length ? 'false' : 'true');
  goLabel.textContent = on.length
    ? 'Subscribe to ' + on.length + ' letter' + (on.length > 1 ? 's' : '')
    : 'Pick a letter first';
  if (announce) {
    live.textContent = on.length
      ? n + ' letters a month, about ' + mins + ' minutes of reading.'
      : 'No letters selected.';
  }
}

// next calendar date strictly after today that a letter is sent
function nextSend(p, from) {
  const d = new Date(from.getFullYear(), from.getMonth(), from.getDate());
  for (let k = 1; k <= 14; k++) {
    d.setDate(d.getDate() + 1);
    const wd = d.getDay();
    if (p.dataset.day === 'weekday' ? wd > 0 && wd < 6 : wd === +p.dataset.day) return new Date(d);
  }
  return d;
}

function mask(v) {
  const [user, domain] = v.split('@');
  return user.slice(0, 1) + '•'.repeat(Math.max(2, Math.min(5, user.length - 1))) + '@' + domain;
}

function showError(on) {
  err.hidden = !on;
  if (on) {
    email.setAttribute('aria-invalid', 'true');
    email.setAttribute('aria-describedby', err.id);
  } else {
    email.removeAttribute('aria-invalid');
    email.removeAttribute('aria-describedby');
  }
}

picks.forEach((p) => p.addEventListener('change', () => update(true)));
email.addEventListener('input', () => { if (!err.hidden && email.validity.valid) showError(false); });

form.addEventListener('submit', (ev) => {
  ev.preventDefault();
  const on = chosen();
  if (!on.length) {
    letters.removeAttribute('data-shake');
    void letters.offsetWidth;
    letters.setAttribute('data-shake', '');
    picks[0].focus();
    live.textContent = 'Pick at least one letter to subscribe.';
    return;
  }
  const v = email.value.trim();
  if (!v || !email.checkValidity() || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) {
    showError(true);
    email.focus();
    return;
  }
  showError(false);
  const today = new Date();
  const sched = on.map((p) => ({ p, at: nextSend(p, today) })).sort((a, b) => a.at - b.at);
  const first = sched[0];
  const diff = Math.round((first.at - new Date(today.getFullYear(), today.getMonth(), today.getDate())) / 864e5);
  root.querySelector('[data-mask]').textContent = mask(v);
  root.querySelector('[data-first]').textContent =
    names[first.p.value] + ', ' + (diff === 1 ? 'tomorrow' : fmtDay.format(first.at));
  root.querySelector('[data-stamp]').textContent = fmtStamp.format(today);
  const list = root.querySelector('[data-list]');
  list.replaceChildren(...sched.map((s, i) => {
    const li = document.createElement('li');
    li.style.setProperty('--i', i);
    const b = document.createElement('b'); b.textContent = names[s.p.value];
    const sp = document.createElement('span'); sp.textContent = when[s.p.value];
    li.append(b, sp);
    return li;
  }));
  form.hidden = true;
  done.hidden = false;
  done.focus({ preventScroll: true });
});

letters.addEventListener('animationend', () => letters.removeAttribute('data-shake'));

back.addEventListener('click', () => {
  done.hidden = true;
  form.hidden = false;
  picks[0].focus({ preventScroll: true });
});

update(false);

css:
.bko-wordmark {
  /* re-theme with these four */
  --bko-wordmark-bg: oklch(18.5% 0.014 58);
  --bko-wordmark-bone: oklch(92% 0.022 82);
  --bko-wordmark-brass: oklch(78% 0.115 76);
  --bko-wordmark-gutter: clamp(16px, 5cqi, 64px);

  --bko-wordmark-muted: color-mix(in oklch, var(--bko-wordmark-bone) 58%, var(--bko-wordmark-bg));
  --bko-wordmark-faint: color-mix(in oklch, var(--bko-wordmark-bone) 34%, var(--bko-wordmark-bg));
  --bko-wordmark-rule: color-mix(in oklch, var(--bko-wordmark-bone) 13%, transparent);
  --bko-wordmark-fs: 25cqi;
  --bko-wordmark-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  container-name: bko-wordmark;
  box-sizing: border-box;
  position: relative;
  width: 100%;
  overflow: hidden;
  background:
    radial-gradient(120% 70% at 50% 118%, color-mix(in oklch, var(--bko-wordmark-brass) 14%, transparent), transparent 70%),
    var(--bko-wordmark-bg);
  color: var(--bko-wordmark-bone);
  font: 400 14.5px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p, ul, address) { margin: 0; padding: 0; font-style: normal; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(a):focus-visible { outline: 1.5px solid var(--bko-wordmark-brass); outline-offset: 4px; border-radius: 2px; }
}

.bko-wordmark-top {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(36px, 5cqi, 64px);
  padding: clamp(44px, 7cqi, 96px) var(--bko-wordmark-gutter) clamp(32px, 4.5cqi, 56px);
}

.bko-wordmark-intro { display: grid; gap: 18px; align-content: start; justify-items: start; max-width: 40ch; }
.bko-wordmark-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 650;
  letter-spacing: .32em;
  text-transform: uppercase;
  & svg { width: 30px; height: 30px; fill: none; stroke: var(--bko-wordmark-brass); stroke-width: 1.25; stroke-linecap: square; }
}
.bko-wordmark-line {
  font-size: clamp(19px, 1.1cqi + 13px, 25px);
  line-height: 1.3;
  font-weight: 350;
  letter-spacing: -.012em;
  text-wrap: balance;
  color: var(--bko-wordmark-bone);
}
.bko-wordmark-cta {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 4px;
  padding: 12px 14px 12px 20px;
  border: 1px solid color-mix(in oklch, var(--bko-wordmark-brass) 55%, transparent);
  border-radius: 999px;
  font-size: 13.5px;
  font-weight: 550;
  letter-spacing: .02em;
  color: var(--bko-wordmark-brass);
  transition: background-color .35s var(--bko-wordmark-out), color .35s var(--bko-wordmark-out), border-color .35s;
  & svg {
    width: 26px; height: 26px; padding: 5px;
    border-radius: 50%;
    background: color-mix(in oklch, var(--bko-wordmark-brass) 16%, transparent);
    fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round;
    transition: transform .5s var(--bko-wordmark-out), background-color .35s;
  }
  &:hover { background: var(--bko-wordmark-brass); color: var(--bko-wordmark-bg); border-color: var(--bko-wordmark-brass); }
  &:hover svg { transform: rotate(45deg); background: color-mix(in oklch, var(--bko-wordmark-bg) 14%, transparent); }
}

.bko-wordmark-nav {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 32px 20px;
}
.bko-wordmark-col {
  display: grid;
  gap: 14px;
  align-content: start;
  & h3 {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--bko-wordmark-faint);
  }
  & ul { display: grid; gap: 8px; }
  & a {
    position: relative;
    display: inline-block;
    color: color-mix(in oklch, var(--bko-wordmark-bone) 86%, var(--bko-wordmark-bg));
    transition: color .3s, transform .45s var(--bko-wordmark-out);
  }
  & a:hover { color: var(--bko-wordmark-bone); transform: translateX(3px); }
  & a::before {
    content: "";
    position: absolute;
    left: -12px; top: 50%;
    width: 5px; height: 1px;
    background: var(--bko-wordmark-brass);
    transform: scaleX(0);
    transform-origin: right;
    transition: transform .45s var(--bko-wordmark-out);
  }
  & a:hover::before { transform: scaleX(1); }
}
.bko-wordmark-rooms {
  gap: 14px !important;
  & a { display: grid; gap: 1px; line-height: 1.4; }
  & b { font-weight: 550; color: var(--bko-wordmark-bone); }
  & span { font-size: 13px; color: var(--bko-wordmark-muted); font-variant-numeric: tabular-nums; }
}

.bko-wordmark-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px 28px;
  margin-inline: var(--bko-wordmark-gutter);
  padding-block: 18px;
  border-top: 1px solid var(--bko-wordmark-rule);
  font-size: 12.5px;
  color: var(--bko-wordmark-muted);
}
.bko-wordmark-legal {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
  & a { transition: color .25s; }
  & a:hover { color: var(--bko-wordmark-brass); }
}
.bko-wordmark-geo {
  margin-left: auto;
  font-family: ui-monospace, Menlo, Consolas, monospace;
  font-size: 11.5px;
  letter-spacing: .02em;
  font-variant-numeric: tabular-nums;
  & span { color: var(--bko-wordmark-faint); margin-right: 6px; font-family: system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; font-size: 10.5px; }
}

/* ---------- the wordmark ----------
   three layers so nothing fights over one transform:
   .word  focus lift (CSS transition)
   .l     reveal from the floor (CSS transition, staggered by --i)
   .g     proximity spring (written by JS every frame while moving)          */
.bko-wordmark-stage {
  position: relative;
  height: calc(var(--bko-wordmark-fs) * .56);
  margin-top: clamp(28px, 6cqi, 80px);
  padding-inline: clamp(10px, 2.2cqi, 30px);
  font-size: var(--bko-wordmark-fs);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  clip-path: inset(-60% -4% 0 -4%);
  /* the floor fade belongs to the stage, not the glyphs: a letter that rises leaves it behind */
  -webkit-mask: linear-gradient(to top, transparent 0, #000 25%) 0 100% / 100% 300% no-repeat;
  mask: linear-gradient(to top, transparent 0, #000 25%) 0 100% / 100% 300% no-repeat;
  user-select: none;
}
.bko-wordmark-word {
  display: flex;
  flex: none;
  line-height: .74;
  font-weight: 760;
  white-space: nowrap;
  transition: transform .8s var(--bko-wordmark-out);
}
.bko-wordmark:has(:focus-visible) .bko-wordmark-word { transform: translateY(-.05em); }
.bko-wordmark-l {
  display: block;
  transition: transform 1.25s var(--bko-wordmark-out) calc(var(--i) * 75ms), opacity .7s linear calc(var(--i) * 75ms);
  & + .bko-wordmark-l { margin-left: calc(-.03em + var(--k, 0em)); }
}
.bko-wordmark[data-armed]:not([data-in]) .bko-wordmark-l { transform: translateY(78%); opacity: 0; }
.bko-wordmark-g {
  --bko-wordmark-p: 0;
  display: block;
  padding-inline: .015em;
  background: linear-gradient(180deg,
    color-mix(in oklch, var(--bko-wordmark-brass) calc(var(--bko-wordmark-p) * 92%), var(--bko-wordmark-bone)) 8%,
    color-mix(in oklch, color-mix(in oklch, var(--bko-wordmark-brass) calc(var(--bko-wordmark-p) * 70%), var(--bko-wordmark-bone)) 78%, var(--bko-wordmark-bg)) 70%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  will-change: transform;
}

@container bko-wordmark (min-width: 560px) {
  .bko-wordmark-nav { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@container bko-wordmark (min-width: 900px) {
  .bko-wordmark-top { grid-template-columns: minmax(0, 1fr) minmax(0, 1.85fr); }
  .bko-wordmark-nav { padding-top: 6px; }
}
@container bko-wordmark (max-width: 479.98px) {
  .bko-wordmark-geo { margin-left: 0; width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  .bko-wordmark {
    & .bko-wordmark-l { transition: opacity .4s linear; }
    &[data-armed]:not([data-in]) .bko-wordmark-l { transform: none; }
    & .bko-wordmark-word, & .bko-wordmark-col a, & .bko-wordmark-col a::before, & .bko-wordmark-cta svg { transition: none; }
    &:has(:focus-visible) .bko-wordmark-word { transform: none; }
    & .bko-wordmark-col a:hover { transform: none; }
  }
}

