const stage = root.querySelector('.bko-wordmark-stage');
const word = root.querySelector('.bko-wordmark-word');
const outer = [...root.querySelectorAll('.bko-wordmark-l')];
const glyphs = outer.map((l) => l.firstElementChild);
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const N = glyphs.length;

// spring state per letter
const x = new Float32Array(N), v = new Float32Array(N), tgt = new Float32Array(N);
const K = 210, C = 17;          // stiffness / damping: a little overshoot, settles in ~0.6s
let centers = [], wordW = 1, fs = 0;
let pointer = null;             // last {cx, cy} in client space, null when outside
let raf = 0, last = 0;

// Fit the word to the stage width. Two passes: system fonts with optical sizes
// are not perfectly linear in width, so measure at a first guess and correct once.
function fit() {
  const cs = getComputedStyle(stage);
  const avail = stage.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
  if (avail <= 0) return;
  let size = fs || avail / 3.4;
  for (let pass = 0; pass < 2; pass++) {
    root.style.setProperty('--bko-wordmark-fs', size.toFixed(2) + 'px');
    const w = word.offsetWidth;
    if (!w) return;
    size = size * (avail / w);
  }
  fs = size;
  root.style.setProperty('--bko-wordmark-fs', fs.toFixed(2) + 'px');
  wordW = word.offsetWidth;
  // .l elements are positioned against the stage (their offsetParent), as is the pointer
  centers = outer.map((l) => l.offsetLeft + l.offsetWidth / 2);
}

function targets() {
  if (!pointer) { tgt.fill(0); return; }
  const r = stage.getBoundingClientRect();
  const px = pointer.cx - r.left;
  const above = r.top - pointer.cy;            // > 0 when the pointer is above the wordmark
  const vy = above <= 0 ? 1 : Math.max(0.16, 1 - above / (r.height * 2.4));
  const sigma = wordW * 0.1;
  for (let i = 0; i < N; i++) {
    const d = (px - centers[i]) / sigma;
    tgt[i] = Math.exp(-0.5 * d * d) * vy;
  }
}

function tick(t) {
  if (!root.isConnected) return;
  const dt = last ? Math.min(0.034, (t - last) / 1000) : 1 / 60;
  last = t;
  targets();
  const lift = fs * 0.2;
  let moving = false;
  for (let i = 0; i < N; i++) {
    const a = K * (tgt[i] - x[i]) - C * v[i];
    v[i] += a * dt;
    x[i] += v[i] * dt;
    if (Math.abs(tgt[i] - x[i]) > 0.0008 || Math.abs(v[i]) > 0.0008) moving = true;
    else { x[i] = tgt[i]; v[i] = 0; }
    glyphs[i].style.transform = 'translate3d(0,' + (-x[i] * lift).toFixed(2) + 'px,0)';
    glyphs[i].style.setProperty('--bko-wordmark-p', Math.min(1, Math.max(0, x[i])).toFixed(3));
  }
  if (moving || pointer) {
    raf = requestAnimationFrame(tick);
  } else {
    raf = 0; last = 0;
  }
}
function kick() { if (!raf) raf = requestAnimationFrame(tick); }

root.addEventListener('pointermove', (e) => {
  if (reduce.matches) return;
  pointer = { cx: e.clientX, cy: e.clientY };
  kick();
});
root.addEventListener('pointerleave', () => { pointer = null; kick(); });
// a touch that ends should let the letters settle rather than stay lifted
root.addEventListener('pointerup', (e) => { if (e.pointerType !== 'mouse') { pointer = null; kick(); } });

// refit on width changes only: fitting changes the height, which must not re-trigger it
let lastW = -1;
const ro = new ResizeObserver((entries) => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = Math.round(entries[0].contentRect.width);
  if (w === lastW) return;
  lastW = w;
  // outside the observer callback, so the height change is never an RO loop
  requestAnimationFrame(() => { if (!root.isConnected) return; fit(); });
});
fit();
lastW = Math.round(root.getBoundingClientRect().width);
ro.observe(root);

// reveal: letters rise out of the floor the first time the footer is seen
if ('IntersectionObserver' in window && !reduce.matches) {
  // arm without animating: the hidden pose is applied instantly, then revealed on view
  outer.forEach((l) => { l.style.transition = 'none'; });
  root.setAttribute('data-armed', '');
  void root.offsetWidth;
  outer.forEach((l) => { l.style.transition = ''; });
  const io = new IntersectionObserver((entries) => {
    if (!root.isConnected) { io.disconnect(); return; }
    if (entries.some((en) => en.isIntersecting)) {
      root.setAttribute('data-in', '');
      io.disconnect();
    }
  }, { threshold: 0.25 });
  io.observe(stage);
} else {
  root.setAttribute('data-in', '');
}

css:
.bko-status {
  /* re-theme with these four */
  --bko-status-bg: oklch(17.5% 0.007 75);
  --bko-status-ink: oklch(93% 0.008 85);
  --bko-status-ok: oklch(84% 0.19 136);
  --bko-status-warn: oklch(79% 0.15 72);

  --bko-status-bad: color-mix(in oklch, var(--bko-status-warn) 55%, oklch(64% 0.2 32));
  --bko-status-muted: color-mix(in oklch, var(--bko-status-ink) 56%, var(--bko-status-bg));
  --bko-status-faint: color-mix(in oklch, var(--bko-status-ink) 34%, var(--bko-status-bg));
  --bko-status-line: color-mix(in oklch, var(--bko-status-ink) 11%, transparent);
  --bko-status-panel: color-mix(in oklch, var(--bko-status-ink) 4%, var(--bko-status-bg));
  --bko-status-raise: color-mix(in oklch, var(--bko-status-ink) 9%, var(--bko-status-bg));
  --bko-status-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;
  --bko-status-out: cubic-bezier(.2, .9, .25, 1);
  --bko-status-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.2%, 1);
  --bko-status-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bko-status;
  box-sizing: border-box;
  width: 100%;
  background: var(--bko-status-bg);
  color: var(--bko-status-ink);
  font: 400 14.5px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, "Hiragino Sans", "Noto Sans JP", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p, ul) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(a, button, [tabindex]):focus-visible { outline: 2px solid var(--bko-status-ok); outline-offset: 3px; border-radius: 4px; }
}
.bko-status-vh {
  position: absolute !important;
  width: 1px; height: 1px; margin: -1px; padding: 0; border: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

.bko-status-in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "brand" "nav" "health" "base";
  gap: clamp(32px, 4.5cqi, 52px) clamp(24px, 4cqi, 56px);
  padding: clamp(40px, 6cqi, 76px) var(--bko-status-gutter) clamp(20px, 3cqi, 28px);
  max-width: 1320px;
  margin-inline: auto;
}

/* ---------- brand ---------- */
.bko-status-brand { grid-area: brand; display: grid; gap: 14px; align-content: start; }
.bko-status-logo {
  display: inline-flex; align-items: center; gap: 10px;
  justify-self: start;
  font-size: 18px; font-weight: 650; letter-spacing: -.02em;
  & svg { width: 30px; height: 30px; fill: none; stroke: var(--bko-status-ok); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}
.bko-status-tag { max-width: 34ch; color: var(--bko-status-muted); text-wrap: pretty; font-size: 15px; }
.bko-status-regions {
  display: flex; flex-wrap: wrap; gap: 6px;
  & span {
    padding: 3px 8px;
    border: 1px solid var(--bko-status-line);
    border-radius: 999px;
    font: 500 11.5px/1.4 var(--bko-status-mono);
    color: var(--bko-status-muted);
  }
}

/* ---------- nav ---------- */
.bko-status-nav { grid-area: nav; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px 16px; }
.bko-status-col {
  display: grid; gap: 12px; align-content: start;
  & h3 { font: 600 11px/1.3 var(--bko-status-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bko-status-faint); }
  & ul { display: grid; gap: 8px; }
  & a {
    display: inline-block;
    hyphens: auto;
    overflow-wrap: break-word;
    color: color-mix(in oklch, var(--bko-status-ink) 84%, var(--bko-status-bg));
    transition: color .2s;
  }
  & a:hover { color: var(--bko-status-ok); }
}

/* ---------- health ---------- */
.bko-status-health {
  grid-area: health;
  display: grid;
  gap: 12px;
  padding: clamp(16px, 2.4cqi, 24px);
  background: var(--bko-status-panel);
  border: 1px solid var(--bko-status-line);
  border-radius: 14px;
}
.bko-status-head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 4px 12px;
}
.bko-status-dot {
  position: relative;
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--bko-status-ok);
  box-shadow: 0 0 12px color-mix(in oklch, var(--bko-status-ok) 60%, transparent);
  &::after {
    content: "";
    position: absolute;
    inset: -5px;
    border-radius: 50%;
    border: 1.5px solid var(--bko-status-ok);
    animation: bko-status-ping 2.4s cubic-bezier(.2, .7, .3, 1) infinite;
  }
}
.bko-status[data-paused] .bko-status-dot::after { animation-play-state: paused; }
@keyframes bko-status-ping {
  0% { transform: scale(.5); opacity: .9; }
  70%, 100% { transform: scale(1.7); opacity: 0; }
}
.bko-status-state { font-weight: 600; letter-spacing: -.01em; display: inline-block; }
.bko-status-uptime {
  grid-column: 2;
  font: 500 12.5px/1.4 var(--bko-status-mono);
  color: var(--bko-status-muted);
  font-variant-numeric: tabular-nums;
  display: inline-block;
}

.bko-status-strip {
  --bko-status-gap: clamp(1px, .28cqi, 3px);
  position: relative;
  display: grid;
  grid-template-columns: repeat(90, minmax(0, 1fr));
  gap: var(--bko-status-gap);
  height: 34px;
  align-items: end;
  padding-top: 6px;
  cursor: crosshair;
  touch-action: pan-y;
  border-radius: 4px;
  & i {
    display: block;
    height: 26px;
    border-radius: 1.5px;
    background: color-mix(in oklch, var(--bko-status-ok) 78%, var(--bko-status-bg));
    transform-origin: bottom;
    transition: transform .35s var(--bko-status-spring), background-color .2s, opacity .2s;
  }
  & i[data-lvl="1"] { background: var(--bko-status-warn); }
  & i[data-lvl="2"] { background: var(--bko-status-bad); }
  & i[data-cur] { transform: scaleY(1.24); background: var(--bko-status-ink); }
  & i[data-cur][data-lvl="1"] { background: color-mix(in oklch, var(--bko-status-warn) 70%, white); }
  & i[data-cur][data-lvl="2"] { background: color-mix(in oklch, var(--bko-status-bad) 70%, white); }
  &:hover i:not([data-cur]), &:focus-visible i:not([data-cur]) { opacity: .62; }
}
/* first sight: the strip grows in from the left, one day at a time */
.bko-status[data-armed]:not([data-in]) .bko-status-strip i { transform: scaleY(.12); opacity: 0; }
.bko-status[data-in] .bko-status-strip[data-intro] i {
  transition: transform .6s var(--bko-status-spring) calc(var(--i) * 7ms), opacity .3s linear calc(var(--i) * 7ms);
}

.bko-status-axis {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font: 500 11px/1.3 var(--bko-status-mono);
  color: var(--bko-status-faint);
  & span { display: inline-block; }
}
.bko-status-hint { opacity: 0; transition: opacity .25s; }
.bko-status-health:has(.bko-status-strip:focus-visible) .bko-status-hint,
.bko-status-health:has(.bko-status-strip:hover) .bko-status-hint { opacity: 1; }

.bko-status-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px 20px;
  padding-top: 12px;
  border-top: 1px dashed var(--bko-status-line);
}
.bko-status-read {
  font: 500 13px/1.45 var(--bko-status-mono);
  font-variant-numeric: tabular-nums;
  color: var(--bko-status-ink);
  min-height: 1.45em;
  & b { font-weight: 600; color: var(--bko-status-muted); }
  & em { font-style: normal; color: var(--bko-status-warn); }
}
.bko-status-page {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 550;
  color: var(--bko-status-ok);
  & span { display: inline-block; }
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: transform .3s var(--bko-status-out); }
  &:hover svg { transform: translate(2px, -2px); }
}

/* ---------- base ---------- */
.bko-status-base {
  grid-area: base;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 24px;
  padding-top: 18px;
  border-top: 1px solid var(--bko-status-line);
  font-size: 13px;
  color: var(--bko-status-muted);
}
.bko-status-legal {
  display: flex; flex-wrap: wrap; gap: 4px 18px;
  & a { display: inline-block; transition: color .2s; }
  & a:hover { color: var(--bko-status-ink); }
}

.bko-status-locale { position: relative; margin-left: auto; }
.bko-status-lbtn {
  display: inline-flex; align-items: center; gap: 8px;
  min-height: 38px;
  padding: 0 10px 0 11px;
  font: inherit; font-size: 13px; font-weight: 550;
  color: var(--bko-status-ink);
  background: var(--bko-status-panel);
  border: 1px solid var(--bko-status-line);
  border-radius: 9px;
  cursor: pointer;
  transition: background-color .2s, border-color .2s;
  & svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & .bko-status-globe { color: var(--bko-status-muted); }
  & .bko-status-chev { width: 15px; height: 15px; color: var(--bko-status-muted); transition: transform .35s var(--bko-status-spring); }
  &:hover { background: var(--bko-status-raise); }
  &[aria-expanded="true"] { border-color: color-mix(in oklch, var(--bko-status-ok) 45%, transparent); }
  &[aria-expanded="true"] .bko-status-chev { transform: rotate(180deg); }
}
.bko-status-menu {
  position: absolute;
  z-index: 5;
  bottom: calc(100% + 8px);
  right: 0;
  min-width: 200px;
  padding: 5px;
  color: var(--bko-status-ink);
  background: var(--bko-status-raise);
  border: 1px solid color-mix(in oklch, var(--bko-status-ink) 16%, transparent);
  border-radius: 12px;
  box-shadow: 0 18px 40px -12px oklch(0% 0 0 / .6), 0 2px 6px oklch(0% 0 0 / .3);
  transform-origin: bottom right;
  opacity: 0;
  visibility: hidden;
  transform: translateY(6px) scale(.96);
  filter: blur(2px);
  transition: opacity .16s linear, transform .22s var(--bko-status-out), filter .2s, visibility 0s linear .22s;
  &:focus { outline: none; }
  &[data-open] {
    opacity: 1;
    visibility: visible;
    transform: none;
    filter: none;
    transition: opacity .14s linear, transform .38s var(--bko-status-spring), filter .2s, visibility 0s;
  }
  & li {
    display: flex; align-items: center; justify-content: space-between; gap: 18px;
    padding: 8px 10px 8px 30px;
    position: relative;
    border-radius: 8px;
    font-size: 14px;
    cursor: pointer;
    user-select: none;
  }
  & li small { font: 500 11px/1 var(--bko-status-mono); color: var(--bko-status-faint); }
  & li[data-active] { background: color-mix(in oklch, var(--bko-status-ink) 9%, transparent); }
  & li[aria-selected="true"]::before {
    content: "";
    position: absolute;
    left: 11px; top: 50%;
    width: 9px; height: 5px;
    border-left: 1.8px solid var(--bko-status-ok);
    border-bottom: 1.8px solid var(--bko-status-ok);
    transform: translateY(-70%) rotate(-45deg);
  }
  &:has(:focus-visible), &:focus-visible { outline: none; }
}
.bko-status-menu:focus-visible li[data-active] { box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--bko-status-ok) 70%, transparent); }

@container bko-status (min-width: 760px) {
  .bko-status-in {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr);
    grid-template-areas: "brand nav" "health health" "base base";
  }
  .bko-status-head { grid-template-columns: auto auto minmax(0, 1fr); }
  .bko-status-uptime { grid-column: 3; justify-self: end; }
  .bko-status-strip { height: 44px; & i { height: 34px; } }
}
@container bko-status (max-width: 479.98px) {
  .bko-status-locale { margin-left: 0; }
  .bko-status-menu { right: auto; left: 0; transform-origin: bottom left; }
  .bko-status-base { flex-direction: column; align-items: flex-start; }
  .bko-status-col a { font-size: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  .bko-status {
    & .bko-status-dot::after { animation: none; transform: scale(.9); opacity: .4; }
    & .bko-status-strip i { transition: background-color .15s, opacity .15s; }
    &[data-in] .bko-status-strip[data-intro] i { transition: opacity .2s linear; }
    &[data-armed]:not([data-in]) .bko-status-strip i { transform: none; }
    & .bko-status-strip i[data-cur] { transform: none; }
    & .bko-status-menu, & .bko-status-menu[data-open] { transition: opacity .12s linear, visibility 0s; transform: none; filter: none; }
    & .bko-status-lbtn .bko-status-chev, & .bko-status-page svg { transition: none; }
  }
}

