const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const strip = root.querySelector('.bko-status-strip');
const readEl = root.querySelector('[data-read]');
const upEl = root.querySelector('[data-uptime]');
const fromEl = root.querySelector('.bko-status-axis span:first-child');
const locale = root.querySelector('.bko-status-locale');
const btn = root.querySelector('.bko-status-lbtn');
const lname = root.querySelector('[data-lname]');
const menu = root.querySelector('.bko-status-menu');
const opts = [...menu.querySelectorAll('[role="option"]')];

const D = {
  en: { tag: 'Message infrastructure for products that can’t afford to drop a single event.', product: 'Product', queues: 'Queues', webhooks: 'Webhooks', realtime: 'Realtime', pricing: 'Pricing', dev: 'Developers', docs: 'Docs', api: 'API reference', changelog: 'Changelog', sdks: 'SDKs', company: 'Company', about: 'About', careers: 'Careers', security: 'Security', contact: 'Contact', ok: 'All systems operational', uptime: '{p} uptime over 90 days', none: 'No incidents', today: 'Today', hint: '← → to inspect', page: 'Status page', privacy: 'Privacy', terms: 'Terms', dpa: 'DPA', lang: 'Language', min: '{n} min', strip: 'Daily uptime, last 90 days', i1: 'Delayed webhook delivery', i2: 'Dashboard sign-in errors', i3: 'Elevated API latency in eu-west' },
  de: { tag: 'Messaging-Infrastruktur für Produkte, die sich kein einziges verlorenes Event leisten können.', product: 'Produkt', queues: 'Warteschlangen', webhooks: 'Webhooks', realtime: 'Echtzeit', pricing: 'Preise', dev: 'Entwickler', docs: 'Dokumentation', api: 'API-Referenz', changelog: 'Changelog', sdks: 'SDKs', company: 'Unternehmen', about: 'Über uns', careers: 'Karriere', security: 'Sicherheit', contact: 'Kontakt', ok: 'Alle Systeme betriebsbereit', uptime: '{p} Verfügbarkeit in 90 Tagen', none: 'Keine Vorfälle', today: 'Heute', hint: '← → zum Ansehen', page: 'Statusseite', privacy: 'Datenschutz', terms: 'AGB', dpa: 'AVV', lang: 'Sprache', min: '{n} Min.', strip: 'Tägliche Verfügbarkeit, letzte 90 Tage', i1: 'Verzögerte Webhook-Zustellung', i2: 'Fehler bei der Dashboard-Anmeldung', i3: 'Erhöhte API-Latenz in eu-west' },
  fr: { tag: 'L’infrastructure de messagerie des produits qui ne peuvent pas perdre un seul événement.', product: 'Produit', queues: 'Files d’attente', webhooks: 'Webhooks', realtime: 'Temps réel', pricing: 'Tarifs', dev: 'Développeurs', docs: 'Documentation', api: 'Référence API', changelog: 'Nouveautés', sdks: 'SDK', company: 'Entreprise', about: 'À propos', careers: 'Carrières', security: 'Sécurité', contact: 'Contact', ok: 'Tous les systèmes sont opérationnels', uptime: '{p} de disponibilité sur 90 jours', none: 'Aucun incident', today: 'Aujourd’hui', hint: '← → pour consulter', page: 'Page d’état', privacy: 'Confidentialité', terms: 'Conditions', dpa: 'DPA', lang: 'Langue', min: '{n} min', strip: 'Disponibilité quotidienne, 90 derniers jours', i1: 'Livraison des webhooks retardée', i2: 'Erreurs de connexion au tableau de bord', i3: 'Latence API élevée en eu-west' },
  es: { tag: 'Infraestructura de mensajería para productos que no pueden perder ni un solo evento.', product: 'Producto', queues: 'Colas', webhooks: 'Webhooks', realtime: 'Tiempo real', pricing: 'Precios', dev: 'Desarrolladores', docs: 'Documentación', api: 'Referencia de la API', changelog: 'Novedades', sdks: 'SDK', company: 'Empresa', about: 'Nosotros', careers: 'Empleo', security: 'Seguridad', contact: 'Contacto', ok: 'Todos los sistemas operativos', uptime: '{p} de disponibilidad en 90 días', none: 'Sin incidencias', today: 'Hoy', hint: '← → para consultar', page: 'Página de estado', privacy: 'Privacidad', terms: 'Términos', dpa: 'DPA', lang: 'Idioma', min: '{n} min', strip: 'Disponibilidad diaria, últimos 90 días', i1: 'Entrega de webhooks con retraso', i2: 'Errores al iniciar sesión en el panel', i3: 'Latencia elevada de la API en eu-west' },
  ja: { tag: 'ひとつのイベントも取りこぼせないプロダクトのための、メッセージ基盤。', product: 'プロダクト', queues: 'キュー', webhooks: 'Webhook', realtime: 'リアルタイム', pricing: '料金', dev: '開発者向け', docs: 'ドキュメント', api: 'APIリファレンス', changelog: '変更履歴', sdks: 'SDK', company: '会社情報', about: '私たちについて', careers: '採用情報', security: 'セキュリティ', contact: 'お問い合わせ', ok: 'すべてのシステムが正常に稼働中', uptime: '過去90日間の稼働率 {p}', none: 'インシデントなし', today: '今日', hint: '← → で日を選択', page: 'ステータスページ', privacy: 'プライバシー', terms: '利用規約', dpa: 'DPA', lang: '言語', min: '{n}分', strip: '日別の稼働率（過去90日間）', i1: 'Webhook配信の遅延', i2: 'ダッシュボードのログインエラー', i3: 'eu-westでのAPIレイテンシ上昇' }
};
const TAG = { en: 'en-GB', de: 'de-DE', fr: 'fr-FR', es: 'es-ES', ja: 'ja-JP' };
const NAME = { en: 'English', de: 'Deutsch', fr: 'Français', es: 'Español', ja: '日本語' };

// ---- data: 90 days ending today; three incidents, in minutes of impact ----
const DAYS = 90;
const INCIDENTS = [{ ago: 71, key: 'i1', min: 23 }, { ago: 38, key: 'i2', min: 11 }, { ago: 9, key: 'i3', min: 13 }];
const impact = INCIDENTS.reduce((s, x) => s + x.min, 0);          // 47 minutes
const uptime = 1 - impact / (DAYS * 24 * 60);                      // 99.964 %
const today = new Date(); today.setHours(12, 0, 0, 0);
const days = Array.from({ length: DAYS }, (_, i) => {
  const ago = DAYS - 1 - i;
  const date = new Date(today); date.setDate(today.getDate() - ago);
  const inc = INCIDENTS.find((x) => x.ago === ago) || null;
  return { date, inc, lvl: inc ? (inc.min >= 15 ? 2 : 1) : 0 };
});

let cur = 'en', fmtDate, fmtPct, idx = DAYS - 1, pinned = DAYS - 1;

// build the bars
root.setAttribute('data-armed', '');
strip.setAttribute('data-intro', '');
strip.replaceChildren(...days.map((d, i) => {
  const b = document.createElement('i');
  b.style.setProperty('--i', i);
  if (d.lvl) b.dataset.lvl = d.lvl;
  return b;
}));
const bars = [...strip.children];

function dayText(i) {
  const d = days[i], t = D[cur];
  const date = fmtDate.format(d.date);
  return d.inc
    ? { date, what: t[d.inc.key], dur: t.min.replace('{n}', d.inc.min) }
    : { date, what: null, dur: t.none };
}

function show(i) {
  if (bars[idx]) bars[idx].removeAttribute('data-cur');
  idx = i;
  bars[idx].setAttribute('data-cur', '');
  const x = dayText(i);
  const b = document.createElement('b'); b.textContent = x.date;
  const parts = [b, ' — '];
  if (x.what) {
    const em = document.createElement('em'); em.textContent = x.what;
    parts.push(em, ' · ' + x.dur);
  } else parts.push(x.dur);
  readEl.replaceChildren(...parts);
  strip.setAttribute('aria-valuenow', i + 1);
  strip.setAttribute('aria-valuetext', x.date + ': ' + (x.what ? x.what + ', ' + x.dur : x.dur));
}

function swapIn(el, k) {
  if (reduce.matches) return;
  el.animate(
    [{ opacity: 0, filter: 'blur(4px)', transform: 'translateY(5px)' }, { opacity: 1, filter: 'blur(0)', transform: 'none' }],
    { duration: 420, delay: k * 14, easing: 'cubic-bezier(.2,.9,.25,1)', fill: 'backwards' }
  );
}

function apply(loc, animate) {
  cur = loc;
  const t = D[loc];
  root.lang = loc;
  fmtDate = new Intl.DateTimeFormat(TAG[loc], { weekday: 'short', day: 'numeric', month: 'short' });
  fmtPct = new Intl.NumberFormat(TAG[loc], { style: 'percent', minimumFractionDigits: 3, maximumFractionDigits: 3 });
  let k = 0;
  root.querySelectorAll('[data-t]').forEach((el) => {
    const txt = t[el.dataset.t];
    if (txt == null || el.textContent === txt) return;
    el.textContent = txt;
    if (animate) swapIn(el, k++);
  });
  upEl.textContent = t.uptime.replace('{p}', fmtPct.format(uptime));
  fromEl.textContent = new Intl.DateTimeFormat(TAG[loc], { day: 'numeric', month: 'short' }).format(days[0].date);
  if (animate) { swapIn(upEl, k++); swapIn(fromEl, k++); }
  strip.setAttribute('aria-label', t.strip);
  menu.setAttribute('aria-label', t.lang);
  lname.textContent = NAME[loc];
  btn.setAttribute('aria-label', t.lang + ': ' + NAME[loc]);
  opts.forEach((o) => o.setAttribute('aria-selected', String(o.dataset.loc === loc)));
  show(idx);
  if (animate) swapIn(readEl, k++);
}

// ---- the strip is a slider over days ----
strip.addEventListener('pointermove', (e) => {
  const r = strip.getBoundingClientRect();
  const i = Math.max(0, Math.min(DAYS - 1, Math.floor((e.clientX - r.left) / r.width * DAYS)));
  if (i !== idx) show(i);
});
strip.addEventListener('pointerleave', () => show(pinned));
strip.addEventListener('click', () => { pinned = idx; });
strip.addEventListener('keydown', (e) => {
  const step = { ArrowLeft: -1, ArrowDown: -1, ArrowRight: 1, ArrowUp: 1, PageDown: -7, PageUp: 7 }[e.key];
  let n;
  if (step) n = pinned + step;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = DAYS - 1;
  else return;
  e.preventDefault();
  pinned = Math.max(0, Math.min(DAYS - 1, n));
  show(pinned);
});

// ---- locale listbox ----
const uid = 'bko-status-' + Math.random().toString(36).slice(2, 8);
opts.forEach((o, i) => { o.id = uid + '-o' + i; });
let open = false, active = 0, typed = '', typedAt = 0;

function setActive(i) {
  active = Math.max(0, Math.min(opts.length - 1, i));
  opts.forEach((o, j) => o.toggleAttribute('data-active', j === active));
  menu.setAttribute('aria-activedescendant', opts[active].id);
}
function openMenu() {
  open = true;
  btn.setAttribute('aria-expanded', 'true');
  menu.setAttribute('data-open', '');
  setActive(opts.findIndex((o) => o.dataset.loc === cur));
  menu.focus({ preventScroll: true });
}
function closeMenu(refocus) {
  open = false;
  btn.setAttribute('aria-expanded', 'false');
  menu.removeAttribute('data-open');
  if (refocus) btn.focus({ preventScroll: true });
}
function choose(i) {
  const loc = opts[i].dataset.loc;
  closeMenu(true);
  if (loc !== cur) apply(loc, true);
}
const norm = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

btn.addEventListener('click', () => (open ? closeMenu(true) : openMenu()));
btn.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowUp' || e.key === 'ArrowDown') { e.preventDefault(); openMenu(); }
});
menu.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowDown': setActive(active + 1); break;
    case 'ArrowUp': setActive(active - 1); break;
    case 'Home': setActive(0); break;
    case 'End': setActive(opts.length - 1); break;
    case 'Enter': case ' ': choose(active); break;
    case 'Escape': closeMenu(true); break;
    case 'Tab': closeMenu(false); return;
    default: {
      if (e.key.length !== 1 || e.metaKey || e.ctrlKey || e.altKey) return;
      const now = e.timeStamp;
      typed = (now - typedAt < 700 ? typed : '') + norm(e.key);
      typedAt = now;
      const order = opts.map((_, j) => (active + (typed.length > 1 ? 0 : 1) + j) % opts.length);
      // match the native name or the language code, so "j" finds 日本語 (JA)
      const hit = order.find((j) => [...opts[j].children].some((c) => norm(c.textContent).startsWith(typed)));
      if (hit != null) setActive(hit);
    }
  }
  e.preventDefault();
});
menu.addEventListener('click', (e) => {
  const o = e.target.closest('[role="option"]');
  if (o) choose(opts.indexOf(o));
});
menu.addEventListener('pointermove', (e) => {
  const o = e.target.closest('[role="option"]');
  if (o && opts.indexOf(o) !== active) setActive(opts.indexOf(o));
});
locale.addEventListener('focusout', (e) => {
  if (open && !locale.contains(e.relatedTarget)) closeMenu(false);
});

// ---- pause the status ping when it cannot be seen ----
let onScreen = true;
const setPaused = () => root.toggleAttribute('data-paused', !onScreen || document.hidden);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  setPaused();
};
document.addEventListener('visibilitychange', onVis);

if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((entries) => {
    if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); return; }
    onScreen = entries[entries.length - 1].isIntersecting;
    setPaused();
    if (onScreen && !root.hasAttribute('data-in')) {
      root.setAttribute('data-in', '');
      // the staggered intro transition only applies once, so hovering stays instant afterwards
      setTimeout(() => { if (root.isConnected) strip.removeAttribute('data-intro'); }, 1500);
    }
  }, { threshold: 0.15 });
  io.observe(root);
} else {
  root.setAttribute('data-in', '');
}

apply('en', false);

