.bko-sitemap {
  /* re-theme with these three */
  --bko-sitemap-bg: oklch(98.6% 0.004 95);
  --bko-sitemap-ink: oklch(23% 0.03 258);
  --bko-sitemap-accent: oklch(64% 0.175 47);

  --bko-sitemap-muted: color-mix(in oklch, var(--bko-sitemap-ink) 60%, var(--bko-sitemap-bg));
  --bko-sitemap-faint: color-mix(in oklch, var(--bko-sitemap-ink) 38%, var(--bko-sitemap-bg));
  --bko-sitemap-line: color-mix(in oklch, var(--bko-sitemap-ink) 11%, transparent);
  --bko-sitemap-well: color-mix(in oklch, var(--bko-sitemap-ink) 3.5%, var(--bko-sitemap-bg));
  --bko-sitemap-tint: color-mix(in oklch, var(--bko-sitemap-accent) 24%, var(--bko-sitemap-bg));
  --bko-sitemap-deep: color-mix(in oklch, var(--bko-sitemap-accent) 78%, var(--bko-sitemap-ink));
  --bko-sitemap-out: cubic-bezier(.2, .85, .25, 1);
  --bko-sitemap-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bko-sitemap;
  box-sizing: border-box;
  width: 100%;
  background: var(--bko-sitemap-bg);
  color: var(--bko-sitemap-ink);
  border-top: 1px solid var(--bko-sitemap-line);
  font: 400 14.5px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p, ul) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & [hidden] { display: none !important; }
  & :where(a, button, input):focus-visible { outline: 2px solid var(--bko-sitemap-accent); outline-offset: 2px; border-radius: 6px; }
}
.bko-sitemap-vh {
  position: absolute !important;
  width: 1px; height: 1px; margin: -1px; padding: 0; border: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

.bko-sitemap-in {
  display: grid;
  gap: clamp(28px, 4cqi, 44px);
  padding: clamp(36px, 5.5cqi, 68px) var(--bko-sitemap-gutter) clamp(20px, 3cqi, 28px);
  max-width: 1360px;
  margin-inline: auto;
}

/* ---------- top: brand + search ---------- */
.bko-sitemap-top {
  display: grid;
  gap: 24px;
  align-items: end;
}
.bko-sitemap-brand { display: grid; gap: 14px; justify-items: start; }
.bko-sitemap-logo {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 19px; font-weight: 700; letter-spacing: -.025em;
  & svg { width: 30px; height: 30px; fill: none; stroke: var(--bko-sitemap-accent); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.bko-sitemap-pitch { max-width: 44ch; color: var(--bko-sitemap-muted); text-wrap: pretty; }
.bko-sitemap-ctas { display: flex; flex-wrap: wrap; gap: 8px; }
.bko-sitemap-btn {
  display: inline-flex; align-items: center;
  min-height: 38px; padding: 0 15px;
  border-radius: 9px;
  font-size: 13.5px; font-weight: 600;
  background: var(--bko-sitemap-ink);
  color: var(--bko-sitemap-bg);
  border: 1px solid var(--bko-sitemap-ink);
  transition: background-color .2s, color .2s, transform .2s var(--bko-sitemap-out);
  &:hover { background: var(--bko-sitemap-deep); border-color: var(--bko-sitemap-deep); }
  &:active { transform: translateY(1px); }
  &[data-ghost] { background: transparent; color: var(--bko-sitemap-ink); border-color: color-mix(in oklch, var(--bko-sitemap-ink) 22%, transparent); }
  &[data-ghost]:hover { background: var(--bko-sitemap-well); }
}

.bko-sitemap-search { display: grid; gap: 8px; }
.bko-sitemap-field {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 48px;
  padding: 0 10px 0 14px;
  background: oklch(100% 0 0);
  border: 1.5px solid color-mix(in oklch, var(--bko-sitemap-ink) 16%, transparent);
  border-radius: 12px;
  box-shadow: 0 1px 2px color-mix(in oklch, var(--bko-sitemap-ink) 6%, transparent);
  transition: border-color .2s, box-shadow .25s;
  cursor: text;
  & svg { width: 19px; height: 19px; flex: none; fill: none; stroke: var(--bko-sitemap-muted); stroke-width: 1.8; stroke-linecap: round; }
  & input {
    flex: 1; min-width: 0;
    height: 100%;
    font: inherit; font-size: 15.5px;
    color: inherit;
    background: none; border: 0; outline: 0;
    &::placeholder { color: var(--bko-sitemap-faint); }
    &::-webkit-search-cancel-button { filter: grayscale(1); opacity: .6; }
    &:focus-visible { outline: none; }
  }
  & kbd {
    flex: none;
    display: grid; place-items: center;
    width: 24px; height: 24px;
    font: 600 12px/1 ui-monospace, Menlo, monospace;
    color: var(--bko-sitemap-muted);
    border: 1px solid var(--bko-sitemap-line);
    border-bottom-width: 2px;
    border-radius: 6px;
    background: var(--bko-sitemap-well);
    transition: opacity .2s;
  }
  &:focus-within {
    border-color: var(--bko-sitemap-accent);
    box-shadow: 0 0 0 4px color-mix(in oklch, var(--bko-sitemap-accent) 18%, transparent);
  }
  &:focus-within kbd, &:has(input:not(:placeholder-shown)) kbd { opacity: 0; }
}
.bko-sitemap-count {
  font-size: 12.5px;
  color: var(--bko-sitemap-muted);
  font-variant-numeric: tabular-nums;
  & b { color: var(--bko-sitemap-ink); font-weight: 650; }
}

/* ---------- the map ---------- */
.bko-sitemap-grid {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  border-top: 1px solid var(--bko-sitemap-ink);
}
.bko-sitemap-col {
  border-bottom: 1px solid var(--bko-sitemap-line);
  & h3 { font-size: inherit; }
}
.bko-sitemap-hs, .bko-sitemap-ht {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  font: 650 13.5px/1.2 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  letter-spacing: -.005em;
  color: var(--bko-sitemap-ink);
  & small {
    font-size: 11px; font-weight: 600;
    min-width: 20px; padding: 2px 6px;
    text-align: center;
    border-radius: 99px;
    color: var(--bko-sitemap-muted);
    background: var(--bko-sitemap-well);
    border: 1px solid var(--bko-sitemap-line);
    font-variant-numeric: tabular-nums;
  }
}
.bko-sitemap-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: var(--bko-sitemap-accent); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.bko-sitemap-hs { display: none; }
.bko-sitemap-ht {
  min-height: 54px;
  padding: 0 2px;
  background: none;
  border: 0;
  cursor: pointer;
  text-align: left;
  & .bko-sitemap-chev {
    width: 18px; height: 18px; margin-left: auto;
    fill: none; stroke: var(--bko-sitemap-muted); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round;
    transition: transform .4s var(--bko-sitemap-out);
  }
  &[aria-expanded="true"] .bko-sitemap-chev { transform: rotate(180deg); }
}
.bko-sitemap-panel {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows .42s var(--bko-sitemap-out);
  & > ul {
    min-height: 0;
    overflow: hidden;
    display: grid;
    align-content: start;
    gap: 2px;
    transition: visibility 0s;
  }
}
.bko-sitemap-panel li:last-child { padding-bottom: 14px; }
.bko-sitemap-panel a {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  max-width: 100%;
  padding: 5px 0;
  color: color-mix(in oklch, var(--bko-sitemap-ink) 78%, var(--bko-sitemap-bg));
  transition: color .2s;
  & em {
    font-style: normal;
    font-size: 10.5px; font-weight: 650;
    letter-spacing: .02em;
    padding: 1px 6px;
    border-radius: 99px;
    color: var(--bko-sitemap-deep);
    background: var(--bko-sitemap-tint);
    white-space: nowrap;
  }
  & .bko-sitemap-go {
    position: absolute;
    left: calc(100% + 5px);
    top: calc(50% - 7px);
    width: 14px; height: 14px; flex: none;
    fill: none; stroke: var(--bko-sitemap-accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round;
    opacity: 0;
    transform: translateX(-6px);
    transition: opacity .2s, transform .35s var(--bko-sitemap-out);
  }
  &:hover, &:focus-visible { color: var(--bko-sitemap-ink); }
  &:hover .bko-sitemap-go, &:focus-visible .bko-sitemap-go { opacity: 1; transform: none; }
}
.bko-sitemap mark {
  color: inherit;
  background: var(--bko-sitemap-tint);
  border-radius: 3px;
  box-shadow: 0 1.5px 0 var(--bko-sitemap-accent);
  animation: bko-sitemap-mark .32s var(--bko-sitemap-out);
}
@keyframes bko-sitemap-mark {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

.bko-sitemap-empty {
  grid-column: 1 / -1;
  margin-top: 20px;
  padding: 20px;
  text-align: center;
  color: var(--bko-sitemap-muted);
  background: var(--bko-sitemap-well);
  border: 1px dashed color-mix(in oklch, var(--bko-sitemap-ink) 18%, transparent);
  border-radius: 12px;
  text-wrap: balance;
  & b { color: var(--bko-sitemap-ink); }
  & button {
    font: inherit; font-weight: 600;
    color: var(--bko-sitemap-deep);
    background: none; border: 0; padding: 0;
    cursor: pointer;
    text-decoration: underline;
    text-decoration-color: color-mix(in oklch, var(--bko-sitemap-accent) 45%, transparent);
    text-underline-offset: 3px;
  }
  & button:hover { text-decoration-color: currentColor; }
}

/* ---------- base ---------- */
.bko-sitemap-base {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px 24px;
  padding-top: 18px;
  border-top: 1px solid var(--bko-sitemap-line);
  font-size: 12.5px;
  color: var(--bko-sitemap-muted);
}
.bko-sitemap-legal {
  display: flex; flex-wrap: wrap; gap: 4px 16px;
  & a { transition: color .2s; }
  & a:hover { color: var(--bko-sitemap-ink); }
}
.bko-sitemap-meta { margin-left: auto; }

/* ---------- wide: open columns ---------- */
@container bko-sitemap (min-width: 640px) {
  .bko-sitemap-top { grid-template-columns: minmax(0, 1fr) minmax(280px, 400px); column-gap: 48px; }
  .bko-sitemap-grid {
    grid-template-columns: repeat(auto-fill, minmax(146px, 1fr));
    gap: 30px 20px;
    padding-top: 24px;
  }
  .bko-sitemap-col { border-bottom: 0; }
  .bko-sitemap-panel > ul { overflow: visible; }
  .bko-sitemap-hs { display: flex; margin-bottom: 12px; }
  .bko-sitemap-ht { display: none; }
  .bko-sitemap-panel li:last-child { padding-bottom: 0; }
  .bko-sitemap-grid:has(.bko-sitemap-col:hover) .bko-sitemap-col:not(:hover) .bko-sitemap-hs { color: var(--bko-sitemap-muted); }
}
@container bko-sitemap (max-width: 639.98px) {
  .bko-sitemap-meta { margin-left: 0; }
  .bko-sitemap-col:not([data-open]) .bko-sitemap-panel {
    grid-template-rows: 0fr;
    & > ul { visibility: hidden; transition: visibility 0s .42s; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .bko-sitemap {
    & .bko-sitemap-panel { transition: none; }
    & .bko-sitemap-col:not([data-open]) .bko-sitemap-panel > ul { transition: none; }
    & .bko-sitemap-ht .bko-sitemap-chev, & .bko-sitemap-panel a .bko-sitemap-go { transition: none; }
    & mark { animation: none; }
  }
}

