const input = root.querySelector('.bko-sitemap-field input');
const shownEl = root.querySelector('[data-shown]');
const grid = root.querySelector('.bko-sitemap-grid');
const empty = root.querySelector('.bko-sitemap-empty');
const qEl = root.querySelector('[data-q]');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1)';
const OUT = 'cubic-bezier(.2,.85,.25,1)';
const norm = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const uid = 'bko-sitemap-' + Math.random().toString(36).slice(2, 8);

const cols = [...root.querySelectorAll('.bko-sitemap-col')].map((el, i) => {
  const btn = el.querySelector('.bko-sitemap-ht');
  const panel = el.querySelector('.bko-sitemap-panel');
  panel.id = uid + '-p' + i;
  btn.setAttribute('aria-controls', panel.id);
  return { el, btn, counts: [...el.querySelectorAll('[data-n]')], items: [], n: 0 };
});
const items = [];
cols.forEach((c) => c.el.querySelectorAll('li').forEach((li) => {
  const a = li.querySelector('a');
  const label = a.querySelector('[data-label]');
  const it = { li, a, label, text: label.textContent, n: norm(label.textContent), k: norm(a.dataset.k || '').split(' '), col: c, marked: false };
  c.items.push(it);
  items.push(it);
}));

let query = '', saved = null, anims = [];
const compact = () => root.clientWidth < 640;

function setOpen(c, on) {
  c.el.toggleAttribute('data-open', on);
  c.btn.setAttribute('aria-expanded', String(on));
}
cols.forEach((c) => c.btn.addEventListener('click', () => setOpen(c, !c.el.hasAttribute('data-open'))));

function mark(it, nq) {
  if (!nq) {
    if (it.marked) { it.label.textContent = it.text; it.marked = false; }
    return;
  }
  const i = it.n.indexOf(nq);
  const m = document.createElement('mark');
  m.textContent = it.text.slice(i, i + nq.length);
  if (it.marked) m.style.animation = 'none';     // only wipe in a highlight that is new
  it.label.replaceChildren(it.text.slice(0, i), m, it.text.slice(i + nq.length));
  it.marked = true;
}

// visual rects, including any transform still in flight
function snap() {
  const m = new Map();
  m.gridH = grid.offsetHeight;
  cols.forEach((c) => {
    if (c.el.hidden) return;
    m.set(c.el, c.el.getBoundingClientRect());
    c.items.forEach((it) => { if (!it.li.hidden) m.set(it.li, it.li.getBoundingClientRect()); });
  });
  return m;
}

function flip(first) {
  // read everything first, then start every animation: no layout between writes
  const plan = [];
  cols.forEach((c) => {
    if (c.el.hidden) return;
    const a = c.el.getBoundingClientRect(), b = first.get(c.el);
    plan.push({ el: c.el, from: b ? [b.left - a.left, b.top - a.top] : null, kind: 'col' });
    c.items.forEach((it) => {
      if (it.li.hidden) return;
      const r = it.li.getBoundingClientRect(), p = first.get(it.li);
      // items move relative to their column, which carries its own translation
      plan.push({ el: it.li, from: p && b ? [(p.left - b.left) - (r.left - a.left), (p.top - b.top) - (r.top - a.top)] : null, kind: 'li' });
    });
  });
  plan.forEach(({ el, from, kind }) => {
    if (from) {
      if (Math.abs(from[0]) < .5 && Math.abs(from[1]) < .5) return;
      anims.push(el.animate([{ transform: 'translate(' + from[0] + 'px,' + from[1] + 'px)' }, { transform: 'none' }],
        { duration: kind === 'col' ? 560 : 480, easing: SPRING }));
    } else {
      anims.push(el.animate(kind === 'col'
        ? [{ opacity: 0, transform: 'scale(.96)' }, { opacity: 1, transform: 'none' }]
        : [{ opacity: 0, transform: 'translateY(5px)' }, { opacity: 1, transform: 'none' }],
      { duration: 300, delay: 70, easing: OUT, fill: 'backwards' }));
    }
  });
}

function run(raw) {
  const q = raw.trim();
  const nq = norm(q);
  const animate = !reduce.matches && !compact();
  const first = animate ? snap() : null;
  anims.forEach((a) => a.cancel());
  anims = [];
  let shown = 0;
  cols.forEach((c) => {
    c.n = 0;
    c.items.forEach((it) => {
      const inText = !!nq && it.n.includes(nq);
      const hit = !nq || inText || it.k.some((w) => w.startsWith(nq));
      it.li.hidden = !hit;
      mark(it, inText ? nq : '');
      if (hit) c.n++;
    });
    c.el.hidden = c.n === 0;
    c.counts.forEach((e) => { e.textContent = c.n; });
    shown += c.n;
  });
  // on narrow layouts, open every column with a match while searching, then restore
  if (nq && !query) saved = cols.map((c) => c.el.hasAttribute('data-open'));
  if (nq) cols.forEach((c) => setOpen(c, c.n > 0));
  else if (saved) { cols.forEach((c, i) => setOpen(c, saved[i])); saved = null; }
  // hold the map's height while filtering on wide layouts, so the page never
  // collapses under the reader's cursor mid-search
  if (nq && !query && !compact()) grid.style.minHeight = (first ? first.gridH : grid.offsetHeight) + 'px';
  if (!nq) grid.style.minHeight = '';
  query = nq;
  shownEl.textContent = shown;
  empty.hidden = shown > 0;
  qEl.textContent = q;
  if (first) flip(first);
}

input.addEventListener('input', () => run(input.value));

const visibleLinks = () => {
  const narrow = compact();
  return items.filter((it) => !it.li.hidden && !it.col.el.hidden && (!narrow || it.col.el.hasAttribute('data-open'))).map((it) => it.a);
};

input.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' || (e.key === 'Enter' && query)) {
    const v = visibleLinks();
    if (v.length) { e.preventDefault(); v[0].focus(); }
  } else if (e.key === 'Escape' && input.value) {
    e.preventDefault();
    input.value = '';
    run('');
  }
});

grid.addEventListener('keydown', (e) => {
  const a = e.target.closest('a');
  if (!a) return;
  const v = visibleLinks();
  const i = v.indexOf(a);
  if (i < 0) return;
  let to = null;
  if (e.key === 'ArrowDown') to = v[i + 1];
  else if (e.key === 'ArrowUp') to = i ? v[i - 1] : input;
  else if (e.key === 'Home') to = v[0];
  else if (e.key === 'End') to = v[v.length - 1];
  else if (e.key === 'Escape') to = input;
  else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
    const it = items.find((x) => x.a === a);
    const lists = cols.map((c) => c.items.filter((x) => v.includes(x.a))).filter((l) => l.length);
    const ci = lists.findIndex((l) => l.includes(it));
    const row = lists[ci].indexOf(it);
    const next = lists[ci + (e.key === 'ArrowRight' ? 1 : -1)];
    if (next) to = next[Math.min(row, next.length - 1)].a;
  }
  if (to) { e.preventDefault(); to.focus(); }
});

// "/" searches the sitemap while it is at least half in view (and nobody is typing)
let inView = false;
const onSlash = (e) => {
  if (!root.isConnected) { document.removeEventListener('keydown', onSlash); return; }
  if (e.key !== '/' || e.metaKey || e.ctrlKey || e.altKey || e.defaultPrevented) return;
  if (!inView && !root.contains(e.target)) return;
  const t = e.target;
  if (t && t.closest && t.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])')) return;
  e.preventDefault();
  input.focus({ preventScroll: true });
  input.select();
};
document.addEventListener('keydown', onSlash);
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((en) => {
    if (!root.isConnected) { io.disconnect(); document.removeEventListener('keydown', onSlash); return; }
    inView = en[en.length - 1].intersectionRatio >= 0.5;
  }, { threshold: [0, 0.5, 1] });
  io.observe(root);
}

root.querySelectorAll('[data-try]').forEach((b) => b.addEventListener('click', () => {
  input.value = b.dataset.try;
  run(input.value);
  input.focus();
}));

css:
@property --bko-dusk-top { syntax: '<color>'; inherits: true; initial-value: oklch(25% 0.045 256); }
@property --bko-dusk-mid { syntax: '<color>'; inherits: true; initial-value: oklch(31% 0.05 262); }
@property --bko-dusk-low { syntax: '<color>'; inherits: true; initial-value: oklch(47% 0.09 38); }
@property --bko-dusk-ink { syntax: '<color>'; inherits: true; initial-value: oklch(96% 0.012 85); }
@property --bko-dusk-sun { syntax: '<angle>'; inherits: true; initial-value: 130deg; }
@property --bko-dusk-night { syntax: '<number>'; inherits: true; initial-value: .7; }

.bko-dusk {
  /* re-theme with these four; the sky itself is computed from the clock */
  --bko-dusk-amber: oklch(84% 0.135 76);
  --bko-dusk-soil: oklch(16.5% 0.022 205);
  --bko-dusk-bone: oklch(95% 0.012 85);
  --bko-dusk-dark: oklch(22% 0.03 252);

  --bko-dusk-ground: color-mix(in oklch, var(--bko-dusk-top) 20%, var(--bko-dusk-soil));
  --bko-dusk-r: clamp(118px, 24cqi, 290px);
  --bko-dusk-rx: 44cqi;
  --bko-dusk-ry: 84px;
  --bko-dusk-hill: clamp(56px, 8.5cqi, 104px);
  --bko-dusk-out: cubic-bezier(.2, .85, .25, 1);
  --bko-dusk-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bko-dusk;
  box-sizing: border-box;
  width: 100%;
  background: var(--bko-dusk-ground);
  color: var(--bko-dusk-bone);
  font: 400 14.5px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  transition:
    --bko-dusk-top .3s linear, --bko-dusk-mid .3s linear, --bko-dusk-low .3s linear,
    --bko-dusk-sun .3s linear, --bko-dusk-night .3s linear, --bko-dusk-ink .7s var(--bko-dusk-out);
  &[data-tween] { transition: --bko-dusk-ink .7s var(--bko-dusk-out); }

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(a, button):focus-visible { outline: 2px solid var(--bko-dusk-amber); outline-offset: 3px; border-radius: 6px; }
}
.bko-dusk-vh {
  position: absolute !important;
  width: 1px; height: 1px; margin: -1px; padding: 0; border: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

/* ---------- the sky band ---------- */
.bko-dusk-top {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "hero" "dial";
  gap: 28px 48px;
  align-items: end;
  padding: clamp(36px, 5.5cqi, 72px) var(--bko-dusk-gutter) calc(var(--bko-dusk-hill) + clamp(20px, 3cqi, 40px));
  min-height: clamp(420px, 40cqi, 470px);
  background: linear-gradient(180deg, var(--bko-dusk-top) 0%, var(--bko-dusk-mid) 58%, var(--bko-dusk-low) 100%);
  color: var(--bko-dusk-ink);
}
.bko-dusk-sky { position: absolute; inset: 0; z-index: -1; overflow: hidden; pointer-events: none; }
.bko-dusk-stars {
  position: absolute; inset: 0;
  fill: oklch(97% 0.02 92);
  opacity: var(--bko-dusk-night);
}
.bko-dusk-tw { animation: bko-dusk-twinkle 3.4s ease-in-out infinite alternate; animation-delay: calc(var(--i) * -1.15s); }
.bko-dusk[data-paused] .bko-dusk-tw { animation-play-state: paused; }
@keyframes bko-dusk-twinkle { to { opacity: .3; } }

.bko-dusk-orbit {
  position: absolute;
  left: 50%;
  bottom: calc(var(--bko-dusk-hill) * .42);
  width: 0; height: 0;
}
.bko-dusk-sun, .bko-dusk-moon {
  position: absolute;
  border-radius: 50%;
  will-change: transform;
}
.bko-dusk-sun {
  left: -23px; top: -23px; width: 46px; height: 46px;
  background: radial-gradient(circle at 50% 50%, oklch(97% 0.06 95) 0 38%, var(--bko-dusk-amber) 70%);
  box-shadow:
    0 0 0 10px color-mix(in oklch, var(--bko-dusk-amber) 16%, transparent),
    0 0 60px 22px color-mix(in oklch, var(--bko-dusk-amber) 38%, transparent);
  transform: rotate(var(--bko-dusk-sun)) translateY(calc(-1 * var(--bko-dusk-r))) rotate(calc(-1 * var(--bko-dusk-sun)));
}
.bko-dusk-moon {
  left: -15px; top: -15px; width: 30px; height: 30px;
  box-shadow: inset -9px 4px 0 0 oklch(94% 0.02 90), 0 0 24px 2px oklch(94% 0.02 90 / .14);
  transform: rotate(calc(var(--bko-dusk-sun) + 180deg)) translateY(calc(-1 * var(--bko-dusk-r))) rotate(calc(-1 * var(--bko-dusk-sun) - 180deg)) rotate(-20deg);
}
/* a flat elliptical day-arc where trig functions exist; a circle otherwise */
@supports (transform: translateX(calc(sin(30deg) * 1px))) {
  .bko-dusk-sun {
    transform: translate(calc(sin(var(--bko-dusk-sun)) * var(--bko-dusk-rx)), calc(cos(var(--bko-dusk-sun)) * var(--bko-dusk-ry) * -1));
  }
  .bko-dusk-moon {
    transform: translate(calc(sin(var(--bko-dusk-sun) + 180deg) * var(--bko-dusk-rx)), calc(cos(var(--bko-dusk-sun) + 180deg) * var(--bko-dusk-ry) * -1)) rotate(-20deg);
  }
}
.bko-dusk-hills {
  position: absolute;
  left: 0; bottom: -1px;
  width: 100%;
  height: var(--bko-dusk-hill);
  & .bko-dusk-far { fill: color-mix(in oklch, var(--bko-dusk-mid) 30%, var(--bko-dusk-ground)); }
  & .bko-dusk-near { fill: var(--bko-dusk-ground); }
}

.bko-dusk-hero { grid-area: hero; display: grid; gap: clamp(28px, 6cqi, 72px); align-content: space-between; height: 100%; }
.bko-dusk-logo {
  display: inline-flex; align-items: center; gap: 9px;
  justify-self: start;
  font-size: 17px; font-weight: 650; letter-spacing: -.015em;
  & svg { width: 28px; height: 28px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}
.bko-dusk-copy { display: grid; gap: 10px; max-width: 560px; }
.bko-dusk-h {
  font-size: clamp(28px, 2.9cqi + 14px, 50px);
  font-weight: 620;
  line-height: 1.04;
  letter-spacing: -.03em;
  text-wrap: balance;
  max-width: 15ch;
}
.bko-dusk-p { max-width: 42ch; font-size: clamp(15px, .4cqi + 13px, 17px); text-wrap: pretty; opacity: .86; font-variant-numeric: tabular-nums; }

.bko-dusk-dial { grid-area: dial; display: grid; gap: 10px; }
.bko-dusk-readout { display: flex; align-items: baseline; gap: 12px; }
.bko-dusk-time {
  font: 300 clamp(44px, 4.6cqi + 18px, 72px)/1 ui-monospace, Menlo, "SF Mono", Consolas, monospace;
  letter-spacing: -.05em;
  font-variant-numeric: tabular-nums;
}
.bko-dusk-live {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 9px 3px 7px;
  border-radius: 99px;
  border: 1px solid color-mix(in oklch, var(--bko-dusk-ink) 30%, transparent);
  font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase;
  transition: opacity .3s;
  & i { width: 6px; height: 6px; border-radius: 50%; background: var(--bko-dusk-amber); box-shadow: 0 0 8px var(--bko-dusk-amber); }
}
.bko-dusk:not([data-live]) .bko-dusk-live { opacity: 0; }

.bko-dusk-range { display: block; }
.bko-dusk-range input {
  -webkit-appearance: none;
  appearance: none;
  display: block;
  width: 100%;
  height: 30px;
  margin: 0;
  background: transparent;
  accent-color: var(--bko-dusk-amber);
  cursor: grab;
  --bko-dusk-track: linear-gradient(90deg,
    oklch(30% 0.045 235) 0%, oklch(36% 0.05 240) 22.9%, oklch(80% 0.11 66) 28.1%, oklch(90% 0.04 120) 35.4%,
    oklch(86% 0.06 225) 54.2%, oklch(86% 0.1 78) 72.9%, oklch(72% 0.14 52) 80.2%, oklch(42% 0.08 38) 86.5%,
    oklch(30% 0.045 235) 93.75%, oklch(30% 0.045 235) 100%);
  &:active { cursor: grabbing; }
  &:focus-visible { outline: none; }
  &::-webkit-slider-runnable-track {
    height: 10px;
    border-radius: 99px;
    background: var(--bko-dusk-track);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bko-dusk-ink) 22%, transparent);
  }
  &::-moz-range-track {
    height: 10px;
    border-radius: 99px;
    background: var(--bko-dusk-track);
  }
  &::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 24px; height: 24px;
    margin-top: -7px;
    border-radius: 50%;
    background: var(--bko-dusk-bone);
    border: 3px solid var(--bko-dusk-amber);
    box-shadow: 0 3px 10px oklch(0% 0 0 / .35);
    transition: transform .25s var(--bko-dusk-out);
  }
  &::-moz-range-thumb {
    width: 18px; height: 18px;
    border-radius: 50%;
    background: var(--bko-dusk-bone);
    border: 3px solid var(--bko-dusk-amber);
  }
  &:active::-webkit-slider-thumb { transform: scale(1.14); }
  &:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 4px color-mix(in oklch, var(--bko-dusk-amber) 55%, transparent); }
  &:focus-visible::-moz-range-thumb { box-shadow: 0 0 0 4px color-mix(in oklch, var(--bko-dusk-amber) 55%, transparent); }
}
.bko-dusk-ticks {
  display: flex;
  justify-content: space-between;
  padding-inline: 6px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace;
  opacity: .66;
  font-variant-numeric: tabular-nums;
}
.bko-dusk-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
  & button {
    font: inherit; font-size: 13px; font-weight: 550;
    min-height: 34px;
    padding: 0 13px;
    color: inherit;
    background: transparent;
    border: 1px solid color-mix(in oklch, var(--bko-dusk-ink) 34%, transparent);
    border-radius: 99px;
    cursor: pointer;
    transition: background-color .25s, color .25s, border-color .25s, transform .2s var(--bko-dusk-out);
  }
  & button:hover { border-color: var(--bko-dusk-ink); }
  & button:active { transform: scale(.97); }
  & button[aria-pressed="true"] { background: var(--bko-dusk-ink); color: var(--bko-dusk-mid); border-color: var(--bko-dusk-ink); }
}

/* ---------- the ground ---------- */
.bko-dusk-ground {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 32px 48px;
  padding: clamp(8px, 1.5cqi, 16px) var(--bko-dusk-gutter) clamp(20px, 3cqi, 28px);
  background: var(--bko-dusk-ground);
}
.bko-dusk-offer {
  display: grid; gap: 10px; justify-items: start; align-content: start;
  & p { color: color-mix(in oklch, var(--bko-dusk-bone) 64%, var(--bko-dusk-ground)); font-size: 13.5px; }
}
.bko-dusk-cta {
  display: inline-flex; align-items: center;
  min-height: 46px; padding: 0 22px;
  border-radius: 99px;
  font-weight: 650; font-size: 15px;
  color: var(--bko-dusk-dark);
  background: var(--bko-dusk-amber);
  box-shadow: 0 0 0 0 color-mix(in oklch, var(--bko-dusk-amber) 0%, transparent);
  transition: transform .3s var(--bko-dusk-out), box-shadow .4s var(--bko-dusk-out);
  &:hover { transform: translateY(-2px); box-shadow: 0 10px 34px -6px color-mix(in oklch, var(--bko-dusk-amber) 60%, transparent); }
}
.bko-dusk-nav { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
.bko-dusk-col {
  display: grid; gap: 10px; align-content: start;
  & h3 { font-size: 11px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: color-mix(in oklch, var(--bko-dusk-bone) 50%, var(--bko-dusk-ground)); }
  & ul { display: grid; gap: 7px; }
  & a { color: color-mix(in oklch, var(--bko-dusk-bone) 86%, var(--bko-dusk-ground)); transition: color .2s; }
  & a:hover { color: var(--bko-dusk-amber); }
}
.bko-dusk-base {
  grid-column: 1 / -1;
  display: flex; flex-wrap: wrap; align-items: baseline;
  gap: 6px 22px;
  padding-top: 16px;
  border-top: 1px solid color-mix(in oklch, var(--bko-dusk-bone) 12%, transparent);
  font-size: 12.5px;
  color: color-mix(in oklch, var(--bko-dusk-bone) 58%, var(--bko-dusk-ground));
  & ul { display: flex; gap: 16px; }
  & a:hover { color: var(--bko-dusk-bone); }
}
.bko-dusk-quiet { margin-left: auto; font-style: italic; }

@container bko-dusk (min-width: 760px) {
  .bko-dusk-top {
    grid-template-columns: minmax(0, 1.2fr) minmax(300px, .8fr);
    grid-template-areas: "hero dial";
  }
  .bko-dusk { --bko-dusk-rx: 40cqi; --bko-dusk-ry: 118px; }
  .bko-dusk-ground { grid-template-columns: minmax(0, 1fr) minmax(0, 1.6fr); }
}
@container bko-dusk (max-width: 759.98px) {
  .bko-dusk { --bko-dusk-rx: 42cqi; --bko-dusk-ry: 74px; }
  .bko-dusk-top { padding-bottom: calc(var(--bko-dusk-hill) + 96px); }
  .bko-dusk-hero { gap: 40px; }
  .bko-dusk-quiet { margin-left: 0; }
  .bko-dusk-col a { font-size: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  .bko-dusk {
    transition: --bko-dusk-ink .2s linear;
    & .bko-dusk-tw { animation: none; }
    & .bko-dusk-cta, & .bko-dusk-presets button { transition: none; }
    & .bko-dusk-range input::-webkit-slider-thumb { transition: none; }
    & .bko-dusk-cta:hover { transform: none; }
  }
}

