const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const range = root.querySelector('.bko-dusk-range input');
const timeEl = root.querySelector('[data-time]');
const hEl = root.querySelector('[data-h]');
const pEl = root.querySelector('[data-p]');
const presets = [...root.querySelectorAll('.bko-dusk-presets button')];

// Sky keyframes through one day: minute, then top / mid / horizon as [L%, C, H].
const KF = [
  [0,    [15, .03, 255],  [20, .035, 248], [27, .04, 232]],
  [330,  [18, .035, 256], [27, .045, 250], [40, .06, 245]],
  [405,  [46, .06, 246],  [72, .1, 56],    [84, .12, 72]],
  [510,  [66, .09, 238],  [84, .05, 215],  [92, .04, 100]],
  [780,  [64, .11, 240],  [82, .065, 228], [93, .03, 105]],
  [1050, [60, .09, 242],  [80, .08, 80],   [88, .1, 78]],
  [1155, [38, .07, 252],  [63, .15, 42],   [78, .14, 66]],
  [1245, [22, .045, 256], [30, .05, 262],  [45, .09, 38]],
  [1350, [15, .03, 255],  [20, .035, 248], [27, .04, 232]],
  [1440, [15, .03, 255],  [20, .035, 248], [27, .04, 232]]
];
const SUNRISE = 405, SUNSET = 1155;                    // 06:45 and 19:15
const LIGHT = 370, WAKE = 400, FOCUS = 540, FOCUS_END = 750, WIND = 1290, SLEEP = 1330;

const smooth = (t) => t * t * (3 - 2 * t);
function mix(a, b, t) {
  let dh = b[2] - a[2];
  if (dh > 180) dh -= 360; else if (dh < -180) dh += 360;
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, (a[2] + dh * t + 360) % 360];
}
const css = (c) => 'oklch(' + c[0].toFixed(2) + '% ' + c[1].toFixed(4) + ' ' + c[2].toFixed(1) + ')';
function sky(t) {
  let k = 0;
  while (k < KF.length - 2 && KF[k + 1][0] <= t) k++;
  const a = KF[k], b = KF[k + 1];
  const u = smooth((t - a[0]) / (b[0] - a[0]));
  return [1, 2, 3].map((j) => mix(a[j], b[j], u));
}
// sun angle: -90deg at sunrise, 0 at solar noon, +90 at sunset, under the hills at night.
// m may run past 1440 during a time-lapse; the angle keeps turning the same way.
function sunDeg(m) {
  const day = Math.floor(m / 1440), t = m - day * 1440;
  let a;
  if (t >= SUNRISE && t <= SUNSET) a = -90 + 180 * (t - SUNRISE) / (SUNSET - SUNRISE);
  else {
    a = 90 + 180 * (((t - SUNSET) + 1440) % 1440) / (1440 - (SUNSET - SUNRISE));
    if (t < SUNRISE) a -= 360;
  }
  return a + day * 360;
}
function altitude(t) {
  if (t >= SUNRISE && t <= SUNSET) return Math.sin(Math.PI * (t - SUNRISE) / (SUNSET - SUNRISE));
  return -Math.sin(Math.PI * (((t - SUNSET) + 1440) % 1440) / (1440 - (SUNSET - SUNRISE)));
}

const pad = (n) => String(n).padStart(2, '0');
const hhmm = (t) => pad(Math.floor(t / 60)) + ':' + pad(Math.floor(t % 60));
const until = (t, target) => (target - Math.floor(t) + 1440) % 1440;
function dur(d) {
  const h = Math.floor(d / 60), m = d % 60;
  return h ? (m ? h + ' h ' + m + ' min' : h + ' h') : m + ' min';
}
function copy(t) {
  if (t >= SLEEP || t < LIGHT) return ['Asleep. Rain on slate, 38 dB.', 'Lights went out at 22:10. Sunrise light begins at 06:10 — in ' + dur(until(t, LIGHT)) + '.'];
  if (t < WAKE) return ['Sunrise light is rising.', 'Your lamp has been warming since 06:10. Alarm at 06:40 — in ' + dur(until(t, WAKE)) + '.'];
  if (t < FOCUS) return ['Morning. You slept 8 h 30 min.', 'Sleep score 86, your best this week. Focus mode starts at 09:00.'];
  if (t < FOCUS_END) return ['Focus mode: brown noise.', 'Notifications held until 12:30 — ' + dur(until(t, FOCUS_END)) + ' to go.'];
  if (t < WIND) return ['Wind\u2011down starts at 21:30.', 'In ' + dur(until(t, WIND)) + '. We’ll dim your screen and start the 40\u2011minute routine.'];
  return ['Winding down.', 'Breathing at six a minute, lights at 15%. Lights out at 22:10 — in ' + dur(until(t, SLEEP)) + '.'];
}

let minute = 0, live = true, tween = 0, lastHead = '';
const nowMinute = () => { const d = new Date(); return d.getHours() * 60 + d.getMinutes(); };

function set(m, from) {
  minute = m;
  const t = ((m % 1440) + 1440) % 1440;
  const [top, mid, low] = sky(t);
  const s = root.style;
  s.setProperty('--bko-dusk-top', css(top));
  s.setProperty('--bko-dusk-mid', css(mid));
  s.setProperty('--bko-dusk-low', css(low));
  s.setProperty('--bko-dusk-sun', sunDeg(m).toFixed(2) + 'deg');
  s.setProperty('--bko-dusk-night', Math.min(1, Math.max(0, -altitude(t) * 2.6 + 0.05)).toFixed(3));
  // the copy sits low in the sky, so ink follows the mid/horizon brightness
  const bright = (mid[0] + low[0]) / 2 > 62;
  s.setProperty('--bko-dusk-ink', bright ? 'var(--bko-dusk-dark)' : 'var(--bko-dusk-bone)');

  const label = hhmm(t);
  timeEl.textContent = label;
  const [h, p] = copy(t);
  if (h !== lastHead) {
    hEl.textContent = h;
    if (lastHead && !reduce.matches) {
      [hEl, pEl].forEach((el, i) => el.animate(
        [{ opacity: 0, filter: 'blur(6px)', transform: 'translateY(8px)' }, { opacity: 1, filter: 'blur(0)', transform: 'none' }],
        { duration: 520, delay: i * 60, easing: 'cubic-bezier(.2,.85,.25,1)', fill: 'backwards' }));
    }
    lastHead = h;
  }
  pEl.textContent = p;
  if (from !== 'range') range.value = Math.round(t / 5) * 5 % 1440;
  range.setAttribute('aria-valuetext', label + ', ' + h.replace(/\.$/, ''));
  const snapped = Math.round(t);
  presets.forEach((b) => b.setAttribute('aria-pressed',
    String(b.dataset.at === 'now' ? live : (!live && +b.dataset.at === snapped))));
  root.toggleAttribute('data-live', live);
}

// time-lapse forward to a minute, so the sky passes through everything in between
function goTo(target, thenLive) {
  cancelAnimationFrame(tween);
  live = false;
  const from = minute;
  let to = target + Math.floor(from / 1440) * 1440;
  while (to <= from) to += 1440;
  if (to - from >= 1440) to -= 1440;
  if (reduce.matches || to === from) { live = !!thenLive; tween = 0; set(to); return; }
  const span = to - from;
  const d = Math.min(2200, 520 + span * 1.15);
  const t0 = performance.now();
  root.setAttribute('data-tween', '');
  const step = (now) => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / d);
    const e = k < .5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
    if (k >= 1) { live = !!thenLive; tween = 0; root.removeAttribute('data-tween'); }
    set(from + span * e);
    if (k < 1) tween = requestAnimationFrame(step);
  };
  tween = requestAnimationFrame(step);
}

range.addEventListener('input', () => {
  cancelAnimationFrame(tween);
  tween = 0;
  root.removeAttribute('data-tween');
  live = false;
  // keep the sun turning the short way round when the thumb wraps at midnight
  const t = +range.value, cur = ((minute % 1440) + 1440) % 1440;
  let d = t - cur;
  if (d > 720) d -= 1440; else if (d < -720) d += 1440;
  set(minute + d, 'range');
});

presets.forEach((b) => b.addEventListener('click', () => {
  if (b.dataset.at === 'now') goTo(nowMinute(), true);
  else goTo(+b.dataset.at, false);
}));

// follow the real clock until someone scrubs
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); return; }
  if (live && !tween) set(nowMinute() + Math.floor(minute / 1440) * 1440);
}, 20000);

// pause the twinkle off screen or in a background tab
let onScreen = true;
const setPaused = () => root.toggleAttribute('data-paused', !onScreen || document.hidden);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  setPaused();
};
document.addEventListener('visibilitychange', onVis);
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((en) => {
    if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); return; }
    onScreen = en[en.length - 1].isIntersecting;
    setPaused();
  });
  io.observe(root);
}

set(nowMinute());

css:
.bko-dock {
  /* re-theme with these three; each app tile carries its own --h hue */
  --bko-dock-bg: oklch(97.3% 0.009 84);
  --bko-dock-ink: oklch(24% 0.02 62);
  --bko-dock-accent: oklch(62% 0.16 38);

  --bko-dock-muted: color-mix(in oklch, var(--bko-dock-ink) 60%, var(--bko-dock-bg));
  --bko-dock-faint: color-mix(in oklch, var(--bko-dock-ink) 40%, var(--bko-dock-bg));
  --bko-dock-line: color-mix(in oklch, var(--bko-dock-ink) 10%, transparent);
  --bko-dock-card: oklch(99.6% 0.003 84);
  --bko-dock-size: 36px;
  --bko-dock-gap: 6px;
  --bko-dock-out: cubic-bezier(.2, .85, .25, 1);
  --bko-dock-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1);
  --bko-dock-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bko-dock;
  box-sizing: border-box;
  width: 100%;
  background:
    radial-gradient(circle at 1px 1px, color-mix(in oklch, var(--bko-dock-ink) 10%, transparent) 1px, transparent 1.5px) 0 0 / 22px 22px,
    var(--bko-dock-bg);
  color: var(--bko-dock-ink);
  font: 400 14.5px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & [hidden] { display: none !important; }
  & :where(a, button):focus-visible { outline: 2px solid var(--bko-dock-accent); outline-offset: 3px; border-radius: 6px; }
}

.bko-dock-in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "nav" "stage" "base";
  gap: clamp(28px, 4cqi, 44px) 48px;
  padding: clamp(40px, 6cqi, 76px) var(--bko-dock-gutter) clamp(18px, 2.6cqi, 26px);
  max-width: 1320px;
  margin-inline: auto;
}

.bko-dock-head { grid-area: head; display: grid; gap: 14px; justify-items: start; align-content: start; }
.bko-dock-logo {
  display: inline-flex; align-items: center; gap: 9px;
  font-size: 18px; font-weight: 700; letter-spacing: -.02em;
  & svg { width: 28px; height: 28px; fill: none; stroke: var(--bko-dock-ink); stroke-width: 1.6; stroke-linejoin: round; }
}
.bko-dock-h {
  font-size: clamp(28px, 3cqi + 12px, 46px);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: -.035em;
  text-wrap: balance;
  max-width: 15ch;
}
.bko-dock-p { color: var(--bko-dock-muted); max-width: 40ch; text-wrap: pretty; }

.bko-dock-nav { grid-area: nav; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; align-content: start; }
.bko-dock-col {
  display: grid; gap: 10px; align-content: start;
  & h3 { font-size: 12px; font-weight: 650; color: var(--bko-dock-faint); }
  & ul { display: grid; gap: 7px; }
  & a { font-weight: 500; transition: color .2s; }
  & a:hover { color: var(--bko-dock-accent); }
}

/* ---------- the desktop ---------- */
.bko-dock-stage {
  grid-area: stage;
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  justify-items: center;
  min-height: 400px;
  border-radius: 22px;
  border: 1px solid var(--bko-dock-line);
  background:
    radial-gradient(60% 70% at 12% 100%, oklch(90% 0.06 40 / .9), transparent 70%),
    radial-gradient(55% 80% at 88% 90%, oklch(91% 0.05 160 / .9), transparent 70%),
    radial-gradient(70% 60% at 50% 0%, oklch(94% 0.035 88), transparent 80%),
    oklch(95% 0.02 70);
  box-shadow: inset 0 1px 0 oklch(100% 0 0 / .7), 0 24px 50px -36px color-mix(in oklch, var(--bko-dock-ink) 60%, transparent);
}
.bko-dock-menubar {
  justify-self: stretch;
  display: flex;
  align-items: center;
  gap: 16px;
  height: 30px;
  padding: 0 14px;
  border-radius: 21px 21px 0 0;
  background: oklch(100% 0 0 / .55);
  border-bottom: 1px solid var(--bko-dock-line);
  font-size: 12px;
  font-weight: 500;
  color: color-mix(in oklch, var(--bko-dock-ink) 80%, transparent);
  white-space: nowrap;
  overflow: hidden;
  & span:nth-child(n+3) { display: none; }
}
.bko-dock-mb-logo {
  display: inline-flex; align-items: center; gap: 6px; font-weight: 700;
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linejoin: round; }
}
.bko-dock-clock { margin-left: auto; display: inline !important; font-variant-numeric: tabular-nums; }
.bko-dock-hint {
  align-self: center;
  padding: 0 20px;
  text-align: center;
  font-size: 13.5px;
  color: color-mix(in oklch, var(--bko-dock-ink) 55%, transparent);
  text-wrap: balance;
  transition: opacity .25s;
  & span { display: none; }
  & svg {
    display: block;
    width: 44px; height: 44px;
    margin: 0 auto 10px;
    fill: none;
    stroke: color-mix(in oklch, var(--bko-dock-ink) 22%, transparent);
    stroke-width: 1.2;
    stroke-linejoin: round;
  }
}
.bko-dock-stage:has(.bko-dock-win:not([hidden])) .bko-dock-hint { opacity: 0; }
.bko-dock-bar {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: flex-end;
  gap: var(--bko-dock-gap);
  padding: 8px 10px 12px;
  margin-bottom: 14px;
}
.bko-dock-shelf {
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: calc(var(--bko-dock-size) * .42);
  background: color-mix(in oklch, var(--bko-dock-card) 82%, transparent);
  border: 1px solid color-mix(in oklch, var(--bko-dock-ink) 9%, transparent);
  box-shadow:
    0 1px 0 oklch(100% 0 0 / .8) inset,
    0 18px 40px -18px color-mix(in oklch, var(--bko-dock-ink) 35%, transparent),
    0 2px 6px -2px color-mix(in oklch, var(--bko-dock-ink) 15%, transparent);
  -webkit-backdrop-filter: blur(10px) saturate(1.3);
  backdrop-filter: blur(10px) saturate(1.3);
  transform-origin: 50% 50%;
  will-change: transform;
}
.bko-dock-app {
  position: relative;
  flex: none;
  width: var(--bko-dock-size);
  height: var(--bko-dock-size);
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  transform-origin: 50% 100%;
  will-change: transform;
  -webkit-tap-highlight-color: transparent;
  &:focus-visible { outline: none; }
  &:focus-visible .bko-dock-tile { outline: 2.5px solid var(--bko-dock-ink); outline-offset: 3px; }
}
.bko-dock-tile {
  display: grid;
  place-items: center;
  width: 100%; height: 100%;
  border-radius: 27%;
  background:
    radial-gradient(120% 90% at 30% 0%, oklch(100% 0 0 / .35), transparent 55%),
    linear-gradient(160deg, oklch(76% 0.15 var(--h)), oklch(60% 0.17 calc(var(--h) + 14)));
  box-shadow:
    inset 0 1px 0 oklch(100% 0 0 / .45),
    inset 0 -2px 0 oklch(0% 0 0 / .12),
    0 4px 10px -4px oklch(45% 0.12 var(--h) / .55);
  & svg { width: 56%; height: 56%; fill: none; stroke: oklch(100% 0 0); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(0 1px 0 oklch(30% 0.1 var(--h) / .35)); }
}
.bko-dock-run {
  position: absolute;
  left: 50%; bottom: -8px;
  width: 4px; height: 4px; margin-left: -2px;
  border-radius: 50%;
  background: var(--bko-dock-ink);
  opacity: 0;
  transform: scale(0);
  transition: opacity .2s, transform .45s var(--bko-dock-spring);
}
.bko-dock-app[data-running] .bko-dock-run { opacity: .75; transform: none; }

.bko-dock-tip {
  position: absolute;
  left: 0; top: 0;
  z-index: 3;
  padding: 4px 10px;
  border-radius: 7px;
  background: var(--bko-dock-ink);
  color: var(--bko-dock-bg);
  font-size: 12.5px; font-weight: 600;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transition: opacity .15s;
  &::after {
    content: "";
    position: absolute;
    left: 50%; bottom: -4px;
    width: 8px; height: 8px; margin-left: -4px;
    background: inherit;
    transform: rotate(45deg);
    border-radius: 1px;
  }
  &[data-on] { opacity: 1; }
}

/* ---------- the app window ---------- */
.bko-dock-win {
  --h: 38;
  position: absolute;
  z-index: 4;
  left: 0;
  bottom: 100px;
  width: min(352px, calc(100% - 24px));
  display: grid;
  gap: 8px;
  padding: 15px 16px 14px;
  background: var(--bko-dock-card);
  border: 1px solid var(--bko-dock-line);
  border-top: 4px solid oklch(66% 0.16 var(--h));
  border-radius: 16px;
  box-shadow:
    0 30px 60px -24px color-mix(in oklch, var(--bko-dock-ink) 45%, transparent),
    0 4px 14px -6px color-mix(in oklch, var(--bko-dock-ink) 20%, transparent);
  &:focus { outline: none; }
}
.bko-dock-x {
  position: absolute;
  top: 10px; right: 10px;
  width: 30px; height: 30px;
  display: grid; place-items: center;
  border: 0; border-radius: 8px;
  background: transparent;
  color: var(--bko-dock-muted);
  cursor: pointer;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  &:hover { background: color-mix(in oklch, var(--bko-dock-ink) 7%, transparent); color: var(--bko-dock-ink); }
}
.bko-dock-wbody { display: grid; gap: 6px; }
.bko-dock-wk, .bko-dock-wt { padding-right: 30px; }
.bko-dock-wk {
  font-size: 11.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  color: oklch(52% 0.15 var(--h));
}
.bko-dock-wt { font-size: 18px; font-weight: 700; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; }
.bko-dock-wd { color: var(--bko-dock-muted); font-size: 13.5px; line-height: 1.45; text-wrap: pretty; }
.bko-dock-ws {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 4px;
  & div { display: flex; flex-direction: column-reverse; gap: 0; padding: 7px 10px; border-radius: 9px; background: color-mix(in oklch, oklch(70% 0.12 var(--h)) 12%, var(--bko-dock-card)); }
  & dt { font-size: 11.5px; color: var(--bko-dock-muted); }
  & dd { font-size: 16px; font-weight: 700; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
}
.bko-dock-wgo {
  justify-self: start;
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 2px;
  font-size: 14px; font-weight: 650;
  color: oklch(50% 0.15 var(--h));
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: transform .3s var(--bko-dock-out); }
  &:hover svg { transform: translateX(3px); }
}

.bko-dock-base {
  grid-area: base;
  display: flex; flex-wrap: wrap; align-items: baseline;
  gap: 6px 22px;
  padding-top: 16px;
  border-top: 1px solid var(--bko-dock-line);
  font-size: 12.5px;
  color: var(--bko-dock-muted);
  & ul { display: flex; gap: 16px; }
  & a:hover { color: var(--bko-dock-ink); }
}
.bko-dock-fine { margin-left: auto; font-size: 11.5px; color: var(--bko-dock-faint); }

@container bko-dock (min-width: 460px) {
  .bko-dock { --bko-dock-size: 46px; --bko-dock-gap: 9px; }
  .bko-dock-menubar span:nth-child(n+3) { display: inline; }
  .bko-dock-hint span { display: inline; }
}
@container bko-dock (min-width: 760px) {
  .bko-dock { --bko-dock-size: 58px; --bko-dock-gap: 12px; }
  .bko-dock-in {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-areas: "head nav" "stage stage" "base base";
  }
  .bko-dock-nav { padding-top: 6px; }
  .bko-dock-bar { padding: 10px 12px 14px; }
  .bko-dock-stage { min-height: clamp(340px, 32cqi, 370px); }
}
@container bko-dock (max-width: 759.98px) {
  .bko-dock-fine { margin-left: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .bko-dock {
    & .bko-dock-run { transition: opacity .2s; transform: none; }
    & .bko-dock-wgo svg { transition: none; }
  }
}

