const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const stage = root.querySelector('.bko-dock-stage');
const bar = root.querySelector('.bko-dock-bar');
const shelf = root.querySelector('.bko-dock-shelf');
const apps = [...root.querySelectorAll('.bko-dock-app')];
const tip = root.querySelector('.bko-dock-tip');
const win = root.querySelector('.bko-dock-win');
const wbody = win.querySelector('.bko-dock-wbody');
const wgo = win.querySelector('.bko-dock-wgo span');
const xBtn = win.querySelector('.bko-dock-x');
const SPRING = 'linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1)';
const N = apps.length;
const uid = 'bko-dock-' + Math.random().toString(36).slice(2, 8);
win.id = uid + '-win';
apps.forEach((a) => a.setAttribute('aria-controls', win.id));

const cur = new Float32Array(N).fill(1), tgt = new Float32Array(N).fill(1), off = new Float32Array(N);
let S = 40, centers = [], barW = 1, barX = 0, barY = 0, padB = 12;
let px = null, raf = 0, last = 0, tipIdx = -1, tipW = 0, tipH = 0, openIdx = -1, winAnim = null, pointerIn = false;

let amp = 0.66;
function measure() {
  S = apps[0].offsetWidth;
  // never grow wider than the desktop can hold
  amp = Math.max(0, Math.min(0.66, (stage.clientWidth - bar.offsetWidth - 28) / (S * 2.5)));
  centers = apps.map((a) => a.offsetLeft + a.offsetWidth / 2);
  barW = bar.offsetWidth;
  barX = bar.offsetLeft;
  barY = bar.offsetTop + bar.offsetHeight;
  padB = parseFloat(getComputedStyle(bar).paddingBottom) || 12;
}

function targets() {
  // with a window open the dock barely swells, so it never reaches the window
  const A = reduce.matches ? 0 : (openIdx >= 0 ? Math.min(amp, 0.2) : amp);
  const R = S * 2.9;
  for (let i = 0; i < N; i++) {
    if (px == null) { tgt[i] = 1; continue; }
    const d = Math.abs(px - centers[i]);
    tgt[i] = 1 + (d < R ? A * (Math.cos(Math.PI * d / R) + 1) / 2 : 0);
  }
}

function placeTip() {
  if (tipIdx < 0) return;
  const x = barX + centers[tipIdx] + off[tipIdx];
  const top = barY - padB - S * cur[tipIdx];
  tip.style.transform = 'translate3d(' + (x - tipW / 2).toFixed(1) + 'px,' + (top - tipH - 12).toFixed(1) + 'px,0)';
}

function tick(t) {
  if (!root.isConnected) return;
  const dt = last ? Math.min(0.05, (t - last) / 1000) : 1 / 60;
  last = t;
  targets();
  const k = 1 - Math.exp(-dt * 17);
  let moving = false, E = 0;
  for (let i = 0; i < N; i++) {
    cur[i] += (tgt[i] - cur[i]) * k;
    if (Math.abs(tgt[i] - cur[i]) > 0.0015) moving = true; else cur[i] = tgt[i];
    E += S * (cur[i] - 1);
  }
  // each tile is pushed sideways by the growth of the tiles before it, so the row
  // widens from its centre with no layout at all
  let acc = 0;
  for (let i = 0; i < N; i++) {
    const e = S * (cur[i] - 1);
    off[i] = acc + e / 2 - E / 2;
    acc += e;
    apps[i].style.transform = 'translate3d(' + off[i].toFixed(2) + 'px,0,0) scale(' + cur[i].toFixed(4) + ')';
  }
  shelf.style.transform = 'scaleX(' + ((barW + E) / barW).toFixed(4) + ')';
  placeTip();
  if (moving) raf = requestAnimationFrame(tick);
  else { raf = 0; last = 0; }
}
const kick = () => { if (!raf) raf = requestAnimationFrame(tick); };

function showTip(i) {
  if (openIdx >= 0 || i < 0) { hideTip(); return; }
  if (i !== tipIdx) {
    tip.textContent = apps[i].getAttribute('aria-label');
    tipW = tip.offsetWidth; tipH = tip.offsetHeight;
    tipIdx = i;
  }
  tip.setAttribute('data-on', '');
  placeTip();
}
function hideTip() { tip.removeAttribute('data-on'); }

function nearest() {
  let best = -1, bd = Infinity;
  for (let i = 0; i < N; i++) {
    const d = Math.abs(px - (centers[i] + off[i]));
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}

bar.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch') return;
  pointerIn = true;
  const r = bar.getBoundingClientRect();
  px = e.clientX - r.left;
  showTip(nearest());
  kick();
});
bar.addEventListener('pointerleave', () => {
  pointerIn = false;
  const f = apps.indexOf(root.querySelector('.bko-dock-app:focus-visible'));
  px = f >= 0 ? centers[f] : null;
  if (f >= 0) showTip(f); else hideTip();
  kick();
});

// ---- roving toolbar ----
function rove(i) { apps.forEach((a, j) => { a.tabIndex = j === i ? 0 : -1; }); }
bar.addEventListener('focusin', (e) => {
  const i = apps.indexOf(e.target.closest('.bko-dock-app'));
  if (i < 0) return;
  rove(i);
  if (!pointerIn && e.target.matches(':focus-visible')) { px = centers[i]; showTip(i); kick(); }
});
bar.addEventListener('focusout', (e) => {
  if (bar.contains(e.relatedTarget)) return;
  if (!pointerIn) { px = null; hideTip(); kick(); }
});
bar.addEventListener('keydown', (e) => {
  const i = apps.indexOf(e.target.closest('.bko-dock-app'));
  if (i < 0) return;
  let n = null;
  if (e.key === 'ArrowRight') n = (i + 1) % N;
  else if (e.key === 'ArrowLeft') n = (i - 1 + N) % N;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = N - 1;
  else if (e.key === 'ArrowUp' && openIdx === i) { e.preventDefault(); win.querySelector('a, button').focus(); return; }
  if (n == null) return;
  e.preventDefault();
  apps[n].focus();
});

// ---- launching ----
function bounce(a) {
  if (reduce.matches) return;
  a.firstElementChild.animate(
    [{ transform: 'translateY(0)' }, { transform: 'translateY(-38%)', offset: .3 }, { transform: 'translateY(0)', offset: .58 },
     { transform: 'translateY(-11%)', offset: .76 }, { transform: 'translateY(0)' }],
    { duration: 720, easing: 'cubic-bezier(.33,0,.4,1)' });
}

function openApp(i) {
  const a = apps[i];
  bounce(a);
  a.setAttribute('data-running', '');
  if (openIdx >= 0) apps[openIdx].setAttribute('aria-expanded', 'false');
  openIdx = i;
  a.setAttribute('aria-expanded', 'true');
  const tpl = root.querySelector('template[data-for="' + a.dataset.app + '"]');
  wbody.replaceChildren(tpl.content.cloneNode(true));
  const name = a.getAttribute('aria-label');
  wgo.textContent = 'Open ' + name;
  win.setAttribute('aria-label', name);
  win.style.setProperty('--h', a.style.getPropertyValue('--h'));
  win.hidden = false;
  hideTip();
  // centre the window over its icon, clamped to the stage, and grow it from there
  const sw = stage.clientWidth, ww = win.offsetWidth;
  const ix = barX + centers[i];
  const x = Math.max(12, Math.min(sw - ww - 12, ix - ww / 2));
  win.style.left = x + 'px';
  // sit above the dock's tallest magnified tile
  win.style.bottom = (stage.clientHeight - bar.offsetTop + S * 0.2 + 10).toFixed(0) + 'px';
  win.style.transformOrigin = (ix - x).toFixed(1) + 'px calc(100% + ' + (S * 0.2 + 10 + bar.offsetHeight / 2).toFixed(0) + 'px)';
  kick();
  if (winAnim) winAnim.cancel();
  winAnim = reduce.matches
    ? win.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 160 })
    : win.animate([{ opacity: 0, transform: 'translateY(28px) scale(.16)' }, { opacity: 1, transform: 'none' }],
      { duration: 560, easing: SPRING });
}
function closeApp(refocus) {
  if (openIdx < 0) return;
  const a = apps[openIdx];
  a.setAttribute('aria-expanded', 'false');
  openIdx = -1;
  if (winAnim) winAnim.cancel();
  winAnim = win.animate(reduce.matches
    ? [{ opacity: 1 }, { opacity: 0 }]
    : [{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateY(28px) scale(.16)' }],
  { duration: reduce.matches ? 120 : 240, easing: 'cubic-bezier(.5,0,.9,.4)' });
  winAnim.onfinish = () => { if (openIdx < 0) win.hidden = true; };
  kick();
  if (refocus) a.focus();
}

apps.forEach((a, i) => a.addEventListener('click', () => (openIdx === i ? closeApp(false) : openApp(i))));
xBtn.addEventListener('click', () => closeApp(true));
root.addEventListener('keydown', (e) => { if (e.key === 'Escape' && openIdx >= 0) { e.preventDefault(); closeApp(true); } });
root.addEventListener('pointerdown', (e) => {
  if (openIdx >= 0 && !win.contains(e.target) && !bar.contains(e.target)) closeApp(false);
});

// ---- menu-bar clock ----
const clock = root.querySelector('[data-clock]');
const fmtClock = new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
const tickClock = () => { clock.textContent = fmtClock.format(new Date()).replace(',', ''); };
tickClock();
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); return; }
  tickClock();
}, 15000);

// ---- size ----
let lastW = -1;
const ro = new ResizeObserver((en) => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = Math.round(en[0].contentRect.width);
  if (w === lastW) return;
  lastW = w;
  requestAnimationFrame(() => {
    if (!root.isConnected) return;
    measure();
    if (openIdx >= 0) closeApp(false);
    kick();
  });
});
measure();
lastW = Math.round(root.getBoundingClientRect().width);
ro.observe(root);

