.bko-offices {
  /* re-theme with these three */
  --bko-offices-bg: oklch(96.4% 0.006 80);
  --bko-offices-ink: oklch(19% 0.006 80);
  --bko-offices-accent: oklch(60% 0.2 33);

  --bko-offices-muted: color-mix(in oklch, var(--bko-offices-ink) 58%, var(--bko-offices-bg));
  --bko-offices-faint: color-mix(in oklch, var(--bko-offices-ink) 34%, var(--bko-offices-bg));
  --bko-offices-line: color-mix(in oklch, var(--bko-offices-ink) 12%, transparent);
  --bko-offices-code: 40px;
  --bko-offices-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;
  --bko-offices-out: cubic-bezier(.2, .85, .25, 1);
  --bko-offices-gutter: clamp(16px, 5cqi, 64px);

  container-type: inline-size;
  container-name: bko-offices;
  box-sizing: border-box;
  width: 100%;
  background: var(--bko-offices-bg);
  color: var(--bko-offices-ink);
  font: 400 14.5px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, address, figure) { margin: 0; padding: 0; font-style: normal; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(a, [tabindex]):focus-visible { outline: 2px solid var(--bko-offices-accent); outline-offset: 4px; border-radius: 2px; }
}

.bko-offices-in {
  display: grid;
  gap: clamp(32px, 5cqi, 56px);
  padding: clamp(40px, 5.5cqi, 72px) var(--bko-offices-gutter) clamp(20px, 3cqi, 28px);
  max-width: 1320px;
  margin-inline: auto;
}

/* ---------- statement ---------- */
.bko-offices-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px 48px;
  align-items: end;
}
.bko-offices-logo {
  display: inline-flex; align-items: center; gap: 10px;
  justify-self: start;
  font-size: 15px; font-weight: 650; letter-spacing: -.01em;
  & svg { width: 28px; height: 28px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; }
}
.bko-offices-h {
  font-size: clamp(30px, 3.1cqi + 13px, 54px);
  font-weight: 330;
  line-height: 1.02;
  letter-spacing: -.04em;
  text-wrap: balance;
  max-width: 17ch;
}
.bko-offices-sub {
  max-width: 40ch;
  color: var(--bko-offices-muted);
  text-wrap: pretty;
  & b { color: var(--bko-offices-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
}

/* ---------- coverage band ---------- */
.bko-offices-band { display: grid; gap: 12px; }
.bko-offices-cap {
  display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px;
  font-size: 12px;
  color: var(--bko-offices-muted);
  & span:first-child { color: var(--bko-offices-ink); font-weight: 600; }
}
.bko-offices-tz { font-family: var(--bko-offices-mono); font-size: 11.5px; }
.bko-offices-chart { position: relative; display: grid; gap: 6px; margin-top: 22px; }
.bko-offices-row {
  display: grid;
  grid-template-columns: var(--bko-offices-code) minmax(0, 1fr);
  align-items: center;
}
.bko-offices-code {
  font: 600 11px/1 var(--bko-offices-mono);
  letter-spacing: .04em;
  color: var(--bko-offices-muted);
  transition: color .25s;
}
.bko-offices-track {
  position: relative;
  height: 12px;
  background:
    repeating-linear-gradient(90deg, var(--bko-offices-line) 0 1px, transparent 1px calc(100% / 24)),
    color-mix(in oklch, var(--bko-offices-ink) 3%, transparent);
  border-right: 1px solid var(--bko-offices-line);
}
.bko-offices-bar {
  position: absolute;
  top: 0; bottom: 0;
  background: var(--bko-offices-ink);
  border-radius: 1px;
  transform-origin: left;
  transition: opacity .3s, background-color .3s;
  animation: bko-offices-grow .9s var(--bko-offices-out) backwards;
  animation-delay: calc(var(--i, 0) * 90ms + 150ms);
}
@keyframes bko-offices-grow { from { transform: scaleX(0); } }
.bko-offices-heat {
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  gap: 1px;
  height: 22px;
  & i {
    background: color-mix(in oklch, var(--bko-offices-ink) calc(var(--n) * 17%), var(--bko-offices-bg));
    transition: background-color .4s;
  }
  & i[data-n="0"] { background: repeating-linear-gradient(-45deg, var(--bko-offices-line) 0 1px, transparent 1px 5px); }
}
.bko-offices-sum { margin-top: 4px; }
.bko-offices-axis {
  display: grid;
  grid-template-columns: var(--bko-offices-code) minmax(0, 1fr);
  & div { display: flex; justify-content: space-between; font: 500 10.5px/1 var(--bko-offices-mono); color: var(--bko-offices-faint); }
  & div span:first-child { transform: translateX(-2px); }
  & div span:last-child { transform: translateX(3px); }
}
.bko-offices-now {
  --bko-offices-at: 0;
  position: absolute;
  top: -4px; bottom: 14px;
  left: calc(var(--bko-offices-code) + (100% - var(--bko-offices-code)) * var(--bko-offices-at));
  width: 0;
  pointer-events: none;
  & i { position: absolute; top: 0; bottom: 0; left: -.75px; width: 1.5px; background: var(--bko-offices-accent); }
  & i::before { content: ""; position: absolute; top: -3px; left: -2.25px; width: 6px; height: 6px; border-radius: 50%; background: var(--bko-offices-accent); }
  & span {
    position: absolute;
    bottom: calc(100% + 4px);
    left: 0;
    transform: translateX(-50%);
    padding: 2px 6px;
    border-radius: 4px;
    background: var(--bko-offices-accent);
    color: var(--bko-offices-bg);
    font: 600 10.5px/1.3 var(--bko-offices-mono);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }
}
.bko-offices-note { font-size: 12.5px; color: var(--bko-offices-muted); text-wrap: pretty; & b { color: var(--bko-offices-ink); font-weight: 600; } }

/* a studio card and its band row light each other up */
.bko-offices:has(.bko-offices-card:is(:hover, :focus-within)) .bko-offices-bar,
.bko-offices:has(.bko-offices-row[data-city]:hover) .bko-offices-bar { opacity: .2; }
.bko-offices:has(.bko-offices-card[data-city="lis"]:is(:hover, :focus-within)) .bko-offices-row[data-city="lis"],
.bko-offices:has(.bko-offices-card[data-city="mtl"]:is(:hover, :focus-within)) .bko-offices-row[data-city="mtl"],
.bko-offices:has(.bko-offices-card[data-city="sel"]:is(:hover, :focus-within)) .bko-offices-row[data-city="sel"],
.bko-offices:has(.bko-offices-card[data-city="mel"]:is(:hover, :focus-within)) .bko-offices-row[data-city="mel"],
.bko-offices-row[data-city]:hover {
  & .bko-offices-bar { opacity: 1; background: var(--bko-offices-accent); }
  & .bko-offices-code { color: var(--bko-offices-accent); }
}
.bko-offices:has(.bko-offices-row[data-city="lis"]:hover) .bko-offices-card[data-city="lis"],
.bko-offices:has(.bko-offices-row[data-city="mtl"]:hover) .bko-offices-card[data-city="mtl"],
.bko-offices:has(.bko-offices-row[data-city="sel"]:hover) .bko-offices-card[data-city="sel"],
.bko-offices:has(.bko-offices-row[data-city="mel"]:hover) .bko-offices-card[data-city="mel"] {
  &::before { transform: scaleX(1); }
}

/* ---------- studio cards (subgrid keeps the five rows aligned across cards) ---------- */
.bko-offices-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 20px;
  row-gap: 0;
}
.bko-offices-card {
  position: relative;
  display: grid;
  grid-row: span 5;
  grid-template-rows: subgrid;
  row-gap: 4px;
  padding: 16px 0 28px;
  border-top: 1px solid var(--bko-offices-ink);
  cursor: default;
  &::before {
    content: "";
    position: absolute;
    left: 0; right: 0; top: -2px;
    height: 3px;
    background: var(--bko-offices-accent);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform .5s var(--bko-offices-out);
  }
  &:hover::before, &:focus-within::before { transform: scaleX(1); }
  & h3 { font-size: 15px; font-weight: 650; letter-spacing: -.01em; }
  & address { font-size: 13px; color: var(--bko-offices-muted); line-height: 1.45; }
  & a { justify-self: start; font-size: 13px; color: var(--bko-offices-ink); text-decoration: underline; text-decoration-color: var(--bko-offices-line); text-underline-offset: 3px; overflow-wrap: anywhere; transition: text-decoration-color .2s; }
  & a:hover { text-decoration-color: var(--bko-offices-accent); }
}
.bko-offices-rel {
  margin-left: 4px;
  font: 500 11px/1 var(--bko-offices-mono);
  letter-spacing: 0;
  color: var(--bko-offices-faint);
  font-variant-numeric: tabular-nums;
}
.bko-offices-time {
  font: 300 clamp(30px, 2.4cqi + 16px, 44px)/1.05 var(--bko-offices-mono);
  letter-spacing: -.05em;
  font-variant-numeric: tabular-nums;
  & b { font-weight: inherit; animation: bko-offices-blink 2s steps(1, end) infinite; }
}
.bko-offices[data-paused] .bko-offices-time b { animation-play-state: paused; }
@keyframes bko-offices-blink { 50% { opacity: .2; } }
.bko-offices-state {
  display: flex; align-items: center; gap: 7px;
  font-size: 12.5px;
  color: var(--bko-offices-muted);
  font-variant-numeric: tabular-nums;
  &::before {
    content: "";
    flex: none;
    width: 7px; height: 7px;
    border-radius: 50%;
    border: 1.5px solid var(--bko-offices-faint);
  }
  &[data-open] { color: var(--bko-offices-ink); }
  &[data-open]::before { background: var(--bko-offices-accent); border-color: var(--bko-offices-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bko-offices-accent) 18%, transparent); }
}

/* ---------- base ---------- */
.bko-offices-base {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between;
  gap: 10px 24px;
  padding-top: 16px;
  border-top: 1px solid var(--bko-offices-line);
  font-size: 12.5px;
  color: var(--bko-offices-muted);
  & a { transition: color .2s; }
  & a:hover { color: var(--bko-offices-accent); }
}
.bko-offices-links {
  display: flex; flex-wrap: wrap; gap: 6px 22px;
  font-size: 14px;
  color: var(--bko-offices-ink);
  & sup { font: 600 9.5px/1 var(--bko-offices-mono); color: var(--bko-offices-accent); vertical-align: super; }
}

@container bko-offices (min-width: 720px) {
  .bko-offices-head {
    grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
    & .bko-offices-logo { grid-column: 1 / -1; margin-bottom: 8px; }
    & .bko-offices-sub { justify-self: end; padding-bottom: 8px; }
  }
  .bko-offices-cards { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0 28px; }
  .bko-offices-card { padding-bottom: 8px; }
  .bko-offices { --bko-offices-code: 48px; }
}

@media (prefers-reduced-motion: reduce) {
  .bko-offices {
    & .bko-offices-bar { animation: none; transition: opacity .2s; }
    & .bko-offices-time b { animation: none; }
    & .bko-offices-card::before { transition: none; }
    & .bko-offices-heat i { transition: none; }
  }
}

