const OPEN = 9 * 60, CLOSE = 18 * 60;           // office hours, local to each studio
const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const heat = root.querySelector('.bko-offices-heat');
const nowEl = root.querySelector('.bko-offices-now');
const nowLabel = root.querySelector('[data-now]');
const coveredEl = root.querySelector('[data-covered]');
const tzEl = root.querySelector('[data-tz]');
const overlapEl = root.querySelector('[data-overlap]');
const fig = root.querySelector('.bko-offices-band');
const capId = 'bko-offices-cap-' + Math.random().toString(36).slice(2, 8);
root.querySelector('#bko-offices-cap').id = capId;
fig.setAttribute('aria-labelledby', capId);

const studios = [...root.querySelectorAll('.bko-offices-card')].map((el, i) => {
  const h3 = el.querySelector('h3');
  const rel = document.createElement('small');
  rel.className = 'bko-offices-rel';
  h3.append(' ', rel);
  return {
    el, i, rel,
    city: el.dataset.city,
    name: h3.firstChild.textContent.trim(),
    track: root.querySelector('.bko-offices-row[data-city="' + el.dataset.city + '"] .bko-offices-track'),
    timeEl: el.querySelector('[data-time]'),
    stateEl: el.querySelector('[data-state]'),
    fmt: new Intl.DateTimeFormat('en-GB', {
      timeZone: el.dataset.tz, hourCycle: 'h23', weekday: 'short',
      year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit'
    }),
    off: null
  };
});
const cells = Array.from({ length: 24 }, () => document.createElement('i'));
heat.replaceChildren(...cells);

function parts(s, date) {
  const o = {};
  s.fmt.formatToParts(date).forEach((p) => { o[p.type] = p.value; });
  return o;
}
// minutes ahead of UTC for a studio at this instant (DST included)
function offsetOf(s, date) {
  const p = parts(s, date);
  const asUtc = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute);
  return Math.round((asUtc - Math.floor(date.getTime() / 60000) * 60000) / 60000);
}
const pad = (n) => String(n).padStart(2, '0');
const hm = (m) => pad(Math.floor(((m % 1440) + 1440) % 1440 / 60)) + ':' + pad(((m % 60) + 60) % 60);
function dur(m) {
  const h = Math.floor(m / 60), r = m % 60;
  return h ? (r ? h + ' h ' + r + ' min' : h + ' h') : r + ' min';
}
function rel(d) {
  if (!d) return 'your time';
  const sign = d > 0 ? '+' : '−', a = Math.abs(d);
  return sign + Math.floor(a / 60) + (a % 60 ? ':' + pad(a % 60) : '') + ' h';
}

let viewerOff = null;

// bars, heat and the computed claims, all from the same intervals
function layout(now) {
  const vOff = -now.getTimezoneOffset();
  const offs = studios.map((s) => offsetOf(s, now));
  if (vOff === viewerOff && offs.every((o, i) => o === studios[i].off)) return;
  viewerOff = vOff;
  studios.forEach((s, i) => { s.off = offs[i]; });

  studios.forEach((s) => {
    s.start = ((OPEN - s.off + vOff) % 1440 + 1440) % 1440;     // opening, in the viewer's minutes
    const segs = s.start + (CLOSE - OPEN) <= 1440
      ? [[s.start, CLOSE - OPEN]]
      : [[s.start, 1440 - s.start], [0, s.start + (CLOSE - OPEN) - 1440]];
    s.track.replaceChildren(...segs.map(([a, w]) => {
      const b = document.createElement('span');
      b.className = 'bko-offices-bar';
      b.style.cssText = 'left:' + (a / 14.4) + '%;width:' + (w / 14.4) + '%;--i:' + s.i;
      return b;
    }));
    s.rel.textContent = rel(s.off - vOff);
  });

  const open = (s, m) => ((m - s.start) % 1440 + 1440) % 1440 < CLOSE - OPEN;
  const who = cells.map((_, h) => studios.filter((s) => open(s, h * 60 + 30)));
  who.forEach((w, h) => {
    cells[h].style.setProperty('--n', w.length);
    cells[h].dataset.n = w.length;
    cells[h].title = pad(h) + ':00 — ' + (w.length ? w.map((s) => s.name).join(', ') : 'nobody in');
  });
  coveredEl.textContent = who.filter((w) => w.length).length;

  // longest stretch with the most studios open at once (the day wraps at midnight)
  const max = Math.max(...who.map((w) => w.length));
  const key = who.map((w) => (w.length === max && max > 1 ? w.map((s) => s.city).join('+') : ''));
  let start = key.findIndex((k, h) => k !== key[(h + 23) % 24]);
  if (start < 0) start = 0;
  let best = null;
  for (let k = 0; k < 24;) {
    const h = (start + k) % 24, cur = key[h];
    let len = 1;
    while (len < 24 && key[(h + len) % 24] === cur) len++;
    if (cur && (!best || len > best.len)) best = { h, len, w: who[h] };
    k += len;
  }
  overlapEl.replaceChildren();
  if (best) {
    const b = document.createElement('b');
    b.textContent = best.w.map((s) => s.name).join(' + ');
    overlapEl.append('Longest overlap: ', b, ', ' + dur(best.len * 60) + ' — ' + hm(best.h * 60) + '–' + hm((best.h + best.len) * 60) + ' your time.');
  }
  const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'Local time';
  tzEl.textContent = tz.replace(/_/g, ' ') + ' · UTC' + (vOff >= 0 ? '+' : '−') + Math.floor(Math.abs(vOff) / 60) + (Math.abs(vOff) % 60 ? ':' + pad(Math.abs(vOff) % 60) : '');
}

function status(s, now) {
  const p = parts(s, now);
  const wd = DAYS.indexOf(p.weekday);
  const t = +p.hour * 60 + +p.minute;
  const workday = wd >= 0 && wd <= 4;
  if (workday && t >= OPEN && t < CLOSE) return { open: true, text: 'Open · ' + dur(CLOSE - t) + ' left', p };
  if (workday && t < OPEN) return { open: false, text: 'Opens in ' + dur(OPEN - t), p };
  let days = 0, d = wd;
  do { days++; d = (d + 1) % 7; } while (d > 4);
  const mins = days * 1440 - t + OPEN;
  return { open: false, text: mins < 1440 ? 'Opens in ' + dur(mins) : 'Opens ' + DAYS[d] + ' 09:00', p };
}

function update() {
  const now = new Date();
  layout(now);
  studios.forEach((s) => {
    const st = status(s, now);
    const colon = document.createElement('b');
    colon.textContent = ':';
    s.timeEl.replaceChildren(st.p.hour, colon, st.p.minute);
    s.timeEl.setAttribute('aria-label', st.p.hour + ':' + st.p.minute + ' in ' + s.name);
    s.stateEl.textContent = st.text;
    s.stateEl.toggleAttribute('data-open', st.open);
  });
  const vm = now.getHours() * 60 + now.getMinutes();
  nowEl.style.setProperty('--bko-offices-at', (vm / 1440).toFixed(4));
  nowLabel.textContent = 'Now ' + hm(vm);
}

// tick while visible; the colon blink pauses with it
let onScreen = true;
const setPaused = () => root.toggleAttribute('data-paused', !onScreen || document.hidden);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  setPaused();
  if (!document.hidden) update();
};
document.addEventListener('visibilitychange', onVis);
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((en) => {
    if (!root.isConnected) { io.disconnect(); return; }
    onScreen = en[en.length - 1].isIntersecting;
    setPaused();
  });
  io.observe(root);
}
const iv = setInterval(() => {
  if (!root.isConnected) { clearInterval(iv); document.removeEventListener('visibilitychange', onVis); return; }
  if (onScreen && !document.hidden) update();
}, 15000);

update();

css:
.bko-brief {
  /* re-theme with these three */
  --bko-brief-bg: oklch(95.2% 0.014 95);
  --bko-brief-ink: oklch(15% 0.006 90);
  --bko-brief-acid: oklch(91% 0.2 118);

  --bko-brief-bw: 3px;
  --bko-brief-muted: color-mix(in oklch, var(--bko-brief-ink) 62%, var(--bko-brief-bg));
  --bko-brief-mono: ui-monospace, Menlo, "SF Mono", Consolas, monospace;
  --bko-brief-snap: cubic-bezier(.3, 1.5, .5, 1);
  --bko-brief-drum: linear(0, .012, .05 2.4%, .2 5.3%, .83 15.4%, 1.02 20.2%, 1.09 24.2%, 1.1 27.8%, 1.07 32.6%, 1.01 41%, .99 48.6%, 1);
  --bko-brief-pad: clamp(16px, 3.2cqi, 36px);

  container-type: inline-size;
  container-name: bko-brief;
  box-sizing: border-box;
  width: 100%;
  background: var(--bko-brief-bg);
  color: var(--bko-brief-ink);
  border-top: var(--bko-brief-bw) solid var(--bko-brief-ink);
  font: 500 14.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ul, fieldset, legend) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & [hidden] { display: none !important; }
  & :where(a, button, input):focus-visible { outline: 3px dashed var(--bko-brief-ink); outline-offset: 3px; }
}
.bko-brief-vh {
  position: absolute !important;
  width: 1px; height: 1px; margin: -1px; padding: 0; border: 0;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

/* ---------- ticker ---------- */
.bko-brief-ticker {
  overflow: hidden;
  background: var(--bko-brief-ink);
  color: var(--bko-brief-acid);
  border-bottom: var(--bko-brief-bw) solid var(--bko-brief-ink);
  font: 700 12.5px/36px var(--bko-brief-mono);
  text-transform: uppercase;
  letter-spacing: .06em;
  white-space: nowrap;
}
.bko-brief-track { display: flex; width: max-content; animation: bko-brief-tape 26s linear infinite; }
.bko-brief-tape {
  display: flex; align-items: center; flex: none;
  & span { padding-inline: 18px; }
  & b { color: var(--bko-brief-bg); }
  & i { font-style: normal; font-size: 15px; }
}
.bko-brief-ticker:hover .bko-brief-track, .bko-brief[data-paused] .bko-brief-track { animation-play-state: paused; }
@keyframes bko-brief-tape { to { transform: translateX(-50%); } }

/* ---------- headline ---------- */
.bko-brief-head {
  display: grid;
  gap: clamp(18px, 3cqi, 32px);
  padding: clamp(24px, 4cqi, 44px) var(--bko-brief-pad) clamp(20px, 3.5cqi, 40px);
  border-bottom: var(--bko-brief-bw) solid var(--bko-brief-ink);
}
.bko-brief-logo {
  display: inline-flex; align-items: center; gap: 10px;
  justify-self: start;
  font: 800 15px/1 var(--bko-brief-mono);
  text-transform: uppercase;
  letter-spacing: .12em;
  & svg { width: 26px; height: 26px; fill: none; stroke: currentColor; stroke-width: 3; stroke-linejoin: miter; }
}
.bko-brief-h {
  font-size: clamp(42px, 8.2cqi, 116px);
  font-weight: 900;
  line-height: .86;
  letter-spacing: -.055em;
  text-transform: uppercase;
  & span { display: block; }
  & mark {
    color: var(--bko-brief-ink);
    background: var(--bko-brief-acid);
    padding-inline: .04em;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
  }
}

/* ---------- builder ---------- */
.bko-brief-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  border-bottom: var(--bko-brief-bw) solid var(--bko-brief-ink);
}
.bko-brief-cell { border: 0; min-width: 0; padding: var(--bko-brief-pad); }
.bko-brief-svc { border-bottom: var(--bko-brief-bw) solid var(--bko-brief-ink); }
.bko-brief-cell legend, .bko-brief-lab {
  float: left;
  width: 100%;
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 14px;
  font: 800 12.5px/1 var(--bko-brief-mono);
  text-transform: uppercase;
  letter-spacing: .08em;
  & span { padding: 4px 6px; background: var(--bko-brief-ink); color: var(--bko-brief-acid); }
}
.bko-brief-opts {
  clear: both;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.bko-brief-opt {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "name name" "wk price";
  gap: 18px 8px;
  padding: 12px 12px 10px;
  border: var(--bko-brief-bw) solid var(--bko-brief-ink);
  background: var(--bko-brief-bg);
  cursor: pointer;
  user-select: none;
  transition: transform .2s var(--bko-brief-snap), box-shadow .2s var(--bko-brief-snap), background-color .12s;
  & input { position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none; }
  & b { grid-area: name; font-size: clamp(17px, 1cqi + 12px, 22px); font-weight: 900; text-transform: uppercase; letter-spacing: -.02em; line-height: 1; padding-right: 22px; }
  & small { grid-area: wk; align-self: end; font: 700 11.5px/1 var(--bko-brief-mono); text-transform: uppercase; }
  & em { grid-area: price; align-self: end; font: 800 12.5px/1 var(--bko-brief-mono); font-style: normal; font-variant-numeric: tabular-nums; }
  &::after {
    content: "";
    position: absolute;
    top: 10px; right: 10px;
    width: 15px; height: 15px;
    border: var(--bko-brief-bw) solid var(--bko-brief-ink);
    background: var(--bko-brief-bg);
  }
  &:hover { background: color-mix(in oklch, var(--bko-brief-acid) 30%, var(--bko-brief-bg)); }
  &:has(input:checked) {
    background: var(--bko-brief-acid);
    transform: translate(-4px, -4px);
    box-shadow: 4px 4px 0 var(--bko-brief-ink);
  }
  &:has(input:checked)::after { background: var(--bko-brief-ink); box-shadow: inset 0 0 0 2px var(--bko-brief-acid); }
  &:has(input:focus-visible) { outline: 3px dashed var(--bko-brief-ink); outline-offset: 5px; }
  &:active { transform: translate(0, 0); box-shadow: 0 0 0 var(--bko-brief-ink); }
}

.bko-brief-incl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  margin-top: 22px;
  border-top: 2px solid var(--bko-brief-ink);
  font: 700 11.5px/1.35 var(--bko-brief-mono);
  text-transform: uppercase;
  & li { display: flex; gap: 8px; padding: 9px 10px 9px 0; border-bottom: 2px solid var(--bko-brief-ink); }
  & li::before { content: "+"; font-weight: 800; }
}
.bko-brief-est { display: grid; gap: 18px; align-content: start; }
.bko-brief-start { border: 0; min-width: 0; }
.bko-brief-seg {
  clear: both;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border: var(--bko-brief-bw) solid var(--bko-brief-ink);
  & label {
    position: relative;
    display: grid;
    justify-items: center;
    gap: 2px;
    padding: 9px 4px 8px;
    cursor: pointer;
    transition: background-color .12s, color .12s;
  }
  & label + label { border-left: var(--bko-brief-bw) solid var(--bko-brief-ink); }
  & input { position: absolute; opacity: 0; width: 1px; height: 1px; }
  & b { font-size: 18px; font-weight: 900; text-transform: uppercase; letter-spacing: -.01em; line-height: 1.1; }
  & small { font: 700 10.5px/1 var(--bko-brief-mono); text-transform: uppercase; letter-spacing: .04em; }
  & label:hover { background: color-mix(in oklch, var(--bko-brief-acid) 30%, var(--bko-brief-bg)); }
  & label:has(input:checked) { background: var(--bko-brief-ink); color: var(--bko-brief-acid); }
  & label:has(input:focus-visible) { outline: 3px dashed var(--bko-brief-ink); outline-offset: 3px; z-index: 1; }
}

/* the price: one 0–9 drum per digit, rolled by transform */
.bko-brief-quote { display: grid; gap: 10px; }
.bko-brief-lab { float: none; margin-bottom: 0; }
.bko-brief-total {
  display: flex;
  align-items: flex-start;
  height: 1em;
  overflow: hidden;
  font-size: clamp(54px, 5.6cqi + 12px, 90px);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.04em;
  font-variant-numeric: tabular-nums;
}
.bko-brief-sym { display: block; height: 1em; margin-right: .02em; }
.bko-brief-comma {
  display: block; height: 1em;
  max-width: .4em;
  overflow: hidden;
  transition: max-width .35s cubic-bezier(.2, .8, .2, 1), opacity .25s;
  &[data-lead] { max-width: 0; opacity: 0; }
}
.bko-brief-dg {
  display: block;
  height: 1em;
  max-width: 1em;
  overflow: hidden;
  transition: max-width .35s cubic-bezier(.2, .8, .2, 1), opacity .25s;
  &[data-lead] { max-width: 0; opacity: 0; }
}
.bko-brief-strip {
  display: flex;
  flex-direction: column;
  transform: translateY(calc(var(--v, 0) * -1em));
  transition: transform .8s var(--bko-brief-drum);
  transition-delay: calc(var(--k, 0) * 55ms);
  & span { display: block; height: 1em; line-height: 1; }
}
.bko-brief-facts {
  display: flex; flex-wrap: wrap;
  gap: 6px;
  font: 700 12px/1 var(--bko-brief-mono);
  text-transform: uppercase;
  letter-spacing: .03em;
  & span { padding: 6px 8px; border: 2px solid var(--bko-brief-ink); }
  & b { font-weight: 800; font-variant-numeric: tabular-nums; }
  & i { font-style: normal; }
  & b[data-flash] { animation: bko-brief-flash .6s steps(2, jump-none) 1; }
}
@keyframes bko-brief-flash { 0%, 49% { background: var(--bko-brief-acid); } }
.bko-brief-break { font: 600 12px/1.4 var(--bko-brief-mono); color: var(--bko-brief-muted); text-transform: uppercase; }

.bko-brief-send {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  margin-top: 4px;
}
.bko-brief-mail input {
  width: 100%;
  min-height: 52px;
  padding: 0 14px;
  font: 700 15px/1 var(--bko-brief-mono);
  color: var(--bko-brief-ink);
  background: var(--bko-brief-bg);
  border: var(--bko-brief-bw) solid var(--bko-brief-ink);
  border-radius: 0;
  &::placeholder { color: color-mix(in oklch, var(--bko-brief-ink) 40%, var(--bko-brief-bg)); }
  &:focus-visible { outline: none; background: oklch(100% 0 0); box-shadow: 4px 4px 0 var(--bko-brief-ink); }
  &[aria-invalid="true"] { background: color-mix(in oklch, var(--bko-brief-acid) 40%, var(--bko-brief-bg)); }
}
.bko-brief-go {
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  min-height: 52px;
  padding: 0 20px;
  font: 900 16px/1 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  text-transform: uppercase;
  letter-spacing: .01em;
  color: var(--bko-brief-ink);
  background: var(--bko-brief-acid);
  border: var(--bko-brief-bw) solid var(--bko-brief-ink);
  border-radius: 0;
  box-shadow: 5px 5px 0 var(--bko-brief-ink);
  cursor: pointer;
  transition: transform .12s, box-shadow .12s;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: square; }
  &:hover { transform: translate(-2px, -2px); box-shadow: 7px 7px 0 var(--bko-brief-ink); }
  &:active { transform: translate(5px, 5px); box-shadow: 0 0 0 var(--bko-brief-ink); }
}
.bko-brief-err {
  justify-self: start;
  padding: 6px 8px;
  background: var(--bko-brief-ink);
  color: var(--bko-brief-acid);
  font: 700 12px/1.3 var(--bko-brief-mono);
  text-transform: uppercase;
}
.bko-brief[data-shake] .bko-brief-opts { animation: bko-brief-shake .36s steps(6, end); }
@keyframes bko-brief-shake {
  0%, 100% { transform: none; }
  20%, 60% { transform: translateX(-6px); }
  40%, 80% { transform: translateX(6px); }
}

/* ---------- receipt ---------- */
.bko-brief-done {
  display: grid;
  gap: 12px;
  justify-items: start;
  padding: var(--bko-brief-pad);
  border-bottom: var(--bko-brief-bw) solid var(--bko-brief-ink);
  background: var(--bko-brief-acid);
  transition: clip-path .5s cubic-bezier(.7, 0, .2, 1);
  clip-path: inset(0 0 0 0);
  &:focus { outline: none; }
  @starting-style { clip-path: inset(0 100% 0 0); }
}
.bko-brief-ref { font: 800 13px/1 var(--bko-brief-mono); padding: 6px 8px; background: var(--bko-brief-ink); color: var(--bko-brief-acid); text-transform: uppercase; letter-spacing: .06em; }
.bko-brief-dh { font-size: clamp(26px, 3cqi + 12px, 46px); font-weight: 900; line-height: .95; letter-spacing: -.04em; text-transform: uppercase; max-width: 18ch; text-wrap: balance; }
.bko-brief-dp { font: 600 13px/1.5 var(--bko-brief-mono); text-transform: uppercase; max-width: 70ch; }
.bko-brief-again {
  font: 800 13px/1 var(--bko-brief-mono);
  text-transform: uppercase;
  padding: 10px 12px;
  color: var(--bko-brief-ink);
  background: var(--bko-brief-bg);
  border: var(--bko-brief-bw) solid var(--bko-brief-ink);
  box-shadow: 4px 4px 0 var(--bko-brief-ink);
  cursor: pointer;
  &:active { transform: translate(4px, 4px); box-shadow: none; }
}

/* ---------- link cells ---------- */
.bko-brief-nav {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-bottom: var(--bko-brief-bw) solid var(--bko-brief-ink);
  & a {
    position: relative;
    isolation: isolate;
    display: grid;
    gap: 6px;
    padding: 18px var(--bko-brief-pad) 16px;
    border-bottom: var(--bko-brief-bw) solid var(--bko-brief-ink);
  }
  & a:nth-child(odd) { border-right: var(--bko-brief-bw) solid var(--bko-brief-ink); }
  & a:last-child { grid-column: 1 / -1; border-right: 0; border-bottom: 0; }
  & a::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    background: var(--bko-brief-acid);
    clip-path: inset(100% 0 0 0);
    transition: clip-path .22s cubic-bezier(.7, 0, .3, 1);
  }
  & a:hover::before, & a:focus-visible::before { clip-path: inset(0 0 0 0); }
  & a:focus-visible { outline-offset: -6px; }
  & span { font-size: clamp(20px, 1cqi + 12px, 24px); font-weight: 900; text-transform: uppercase; letter-spacing: -.03em; line-height: 1; white-space: nowrap; }
  & span::after { content: " \2197"; font-weight: 700; display: inline-block; transition: transform .25s var(--bko-brief-snap); }
  & a:hover span::after { transform: translate(3px, -3px); }
  & small { font: 700 11.5px/1.2 var(--bko-brief-mono); text-transform: uppercase; color: var(--bko-brief-muted); overflow-wrap: anywhere; }
}

.bko-brief-base {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between;
  gap: 8px 20px;
  padding: 14px var(--bko-brief-pad) 18px;
  font: 700 11.5px/1.4 var(--bko-brief-mono);
  text-transform: uppercase;
  & ul { display: flex; gap: 16px; }
  & a { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 3px; }
  & a:hover { background: var(--bko-brief-acid); }
}

@container bko-brief (min-width: 560px) {
  .bko-brief-opts { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bko-brief-send { grid-template-columns: minmax(0, 1fr) auto; }
}
@container bko-brief (min-width: 880px) {
  .bko-brief-form { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); }
  .bko-brief-svc { border-bottom: 0; border-right: var(--bko-brief-bw) solid var(--bko-brief-ink); }
  .bko-brief-opts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bko-brief-head { grid-template-columns: minmax(0, 1fr) auto; align-items: start; }
  .bko-brief-logo { grid-column: 2; grid-row: 1; padding-top: 10px; }
  .bko-brief-h { grid-column: 1; grid-row: 1; }
  .bko-brief-nav {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    & a { padding: 16px 20px 14px; }
    & a, & a:nth-child(odd) { border-bottom: 0; border-right: var(--bko-brief-bw) solid var(--bko-brief-ink); }
    & a:last-child { grid-column: auto; border-right: 0; }
  }
}
@container bko-brief (min-width: 1040px) {
  .bko-brief-opts { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .bko-brief {
    & .bko-brief-track { animation: none; }
    & .bko-brief-ticker { text-overflow: clip; }
    & .bko-brief-strip { transition: none; }
    & .bko-brief-dg, & .bko-brief-comma { transition: none; }
    & .bko-brief-opt { transition: background-color .12s; }
    & .bko-brief-opt:has(input:checked) { transform: none; box-shadow: inset 0 0 0 2px var(--bko-brief-ink); }
    & .bko-brief-done { transition: none; }
    & .bko-brief-nav a::before { transition: none; }
    &[data-shake] .bko-brief-opts { animation: none; }
    & .bko-brief-facts b[data-flash] { animation: none; }
  }
}

js:
const form = root.querySelector('.bko-brief-form');
const svcs = [...root.querySelectorAll('input[name="svc"]')];
const starts = [...root.querySelectorAll('input[name="start"]')];
const totalEl = root.querySelector('[data-total]');
const weeksEl = root.querySelector('[data-weeks]');
const weeksLabel = root.querySelector('[data-weeks-label]');
const wk = (n) => n + (n === 1 ? ' week' : ' weeks');
const launchEl = root.querySelector('[data-launch]');
const depositEl = root.querySelector('[data-deposit]');
const breakEl = root.querySelector('[data-break]');
const liveEl = root.querySelector('[data-live]');
const errEl = root.querySelector('[data-err]');
const email = root.querySelector('input[type="email"]');
const done = root.querySelector('.bko-brief-done');
const again = root.querySelector('.bko-brief-again');
const money = new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'GBP', maximumFractionDigits: 0 });
const fmtDay = new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
const fmtMon = new Intl.DateTimeFormat('en-GB', { month: 'short' });
errEl.id = 'bko-brief-err-' + Math.random().toString(36).slice(2, 8);

// the next three calendar months are the bookable starts
const today = new Date();
const months = [1, 2, 3].map((k) => new Date(today.getFullYear(), today.getMonth() + k, 1));
root.querySelectorAll('[data-mon]').forEach((b, i) => { b.textContent = fmtMon.format(months[i]); });
root.querySelectorAll('[data-tick-months], [data-tick-months2]').forEach((b) => {
  b.textContent = months.map((m) => fmtMon.format(m)).join(' · ');
});

// ---- odometer: five 0-9 drums and a comma ----
const SLOTS = 5;
const digits = [];
let comma;
const sym = document.createElement('span');
sym.className = 'bko-brief-sym';
sym.textContent = '£';
totalEl.append(sym);
for (let i = 0; i < SLOTS; i++) {
  if (i === SLOTS - 3) {
    comma = document.createElement('span');
    comma.className = 'bko-brief-comma';
    comma.textContent = ',';
    totalEl.append(comma);
  }
  const dg = document.createElement('span');
  dg.className = 'bko-brief-dg';
  const strip = document.createElement('span');
  strip.className = 'bko-brief-strip';
  strip.style.setProperty('--k', SLOTS - 1 - i);         // rightmost drum rolls first
  for (let n = 0; n < 10; n++) {
    const s = document.createElement('span');
    s.textContent = n;
    strip.append(s);
  }
  dg.append(strip);
  totalEl.append(dg);
  digits.push({ dg, strip });
}
function setTotal(n) {
  const s = String(n).padStart(SLOTS, '0');
  const len = String(n).length;
  digits.forEach((d, i) => {
    d.strip.style.setProperty('--v', s[i]);
    d.dg.toggleAttribute('data-lead', i < SLOTS - len);
  });
  comma.toggleAttribute('data-lead', n < 1000);
}

function firstMonday(d) {
  const x = new Date(d);
  while (x.getDay() !== 1) x.setDate(x.getDate() + 1);
  return x;
}

function plan() {
  const on = svcs.filter((x) => x.checked);
  const weeks = on.reduce((a, x) => a + +x.dataset.w, 0);
  const total = on.reduce((a, x) => a + +x.dataset.p, 0);
  const start = firstMonday(months[Math.max(0, starts.findIndex((r) => r.checked))]);
  const end = new Date(start);
  end.setDate(end.getDate() + weeks * 7 - 3);                  // the Friday of the last week
  // a project running through 21 Dec - 1 Jan gets two extra weeks for the studio's break
  const y = start.getMonth() === 0 ? start.getFullYear() - 1 : start.getFullYear();
  const crosses = weeks > 0 && start <= new Date(y + 1, 0, 1) && end >= new Date(y, 11, 21);
  if (crosses) end.setDate(end.getDate() + 14);
  return { on, weeks, total, start, end, crosses, deposit: Math.round(total * 0.3) };
}

function flash(el, text) {
  if (el.textContent === text) return;
  el.textContent = text;
  el.removeAttribute('data-flash');
  void el.offsetWidth;
  el.setAttribute('data-flash', '');
}

function render(announce) {
  const p = plan();
  setTotal(p.total);
  flash(weeksEl, String(p.weeks));
  weeksLabel.textContent = p.weeks === 1 ? 'week' : 'weeks';
  flash(launchEl, p.weeks ? fmtDay.format(p.end) : '—');
  flash(depositEl, money.format(p.deposit));
  breakEl.hidden = !p.crosses;
  // the drums are decorative; this sentence is what assistive tech reads
  if (announce || !liveEl.textContent) {
    liveEl.textContent = p.weeks
      ? money.format(p.total) + ', ' + wk(p.weeks) + ', launch ' + fmtDay.format(p.end) + '.'
      : 'No services selected.';
  }
  if (p.on.length) errEl.hidden = true;
}

function fail(msg, field) {
  errEl.textContent = msg;
  errEl.hidden = false;
  if (field) {
    field.setAttribute('aria-invalid', 'true');
    field.setAttribute('aria-describedby', errEl.id);
    field.focus();
  }
}

svcs.forEach((x) => x.addEventListener('change', () => render(true)));
starts.forEach((x) => x.addEventListener('change', () => render(true)));
email.addEventListener('input', () => {
  email.removeAttribute('aria-invalid');
  email.removeAttribute('aria-describedby');
  errEl.hidden = true;
});

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const p = plan();
  if (!p.on.length) {
    root.removeAttribute('data-shake');
    void root.offsetWidth;
    root.setAttribute('data-shake', '');
    fail('Pick at least one service first.');
    svcs[0].focus();
    return;
  }
  const v = email.value.trim();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) { fail('We need an email we can reply to.', email); return; }
  const doy = Math.round((today - new Date(today.getFullYear(), 0, 0)) / 864e5);
  root.querySelector('[data-ref]').textContent = 'Brief OC-' + String(doy).padStart(3, '0') + '-' + String(p.total / 100).padStart(3, '0');
  const [user, domain] = v.split('@');
  root.querySelector('[data-summary]').textContent =
    p.on.map((x) => x.value).join(' + ') + ' · ' + money.format(p.total) + ' · ' + wk(p.weeks) + ' · starts ' +
    fmtDay.format(p.start) + ' · launch ' + fmtDay.format(p.end) + ' · reply to ' + user.slice(0, 1) + '•••@' + domain;
  form.hidden = true;
  done.hidden = false;
  done.focus({ preventScroll: true });
});
root.addEventListener('animationend', (e) => { if (e.animationName === 'bko-brief-shake') root.removeAttribute('data-shake'); });
again.addEventListener('click', () => {
  done.hidden = true;
  form.hidden = false;
  svcs[0].focus({ preventScroll: true });
});

// the ticker stops when nobody can see it
let onScreen = true;
const setPaused = () => root.toggleAttribute('data-paused', !onScreen || document.hidden);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  setPaused();
};
document.addEventListener('visibilitychange', onVis);
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((en) => {
    if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); return; }
    onScreen = en[en.length - 1].isIntersecting;
    setPaused();
  });
  io.observe(root);
}

render(false);
